    INSERT INTO "Question" ("id", "assessmentId", "textEn", "textFr", "order", "points", "setNumber") VALUES
      ('bdc85a84-5f15-47d5-b16e-3b84fc6294c7', a_id, $bp$What does the Author's Word say repentance is, using the word metanoia?$bp$, $bp$Que dit le Mot de l'auteur de la repentance, avec le mot metanoia ?$bp$, 0, 1, 1),
      ('82684d39-ce7d-47bf-89b7-fdee6f3dbfa9', a_id, $bp$How does the Introduction describe the three truths of repentance, baptism, and the Holy Spirit?$bp$, $bp$Comment l'Introduction décrit-elle les trois vérités de la repentance, du baptême et du Saint-Esprit ?$bp$, 1, 1, 1),
      ('b32d5dd4-5fd4-41ce-b4ec-3ab899ee746c', a_id, $bp$According to the Introduction, what is the Holy Spirit to the believer?$bp$, $bp$Selon l'Introduction, qu'est le Saint-Esprit pour le croyant ?$bp$, 2, 1, 1),
      ('b3673a83-d719-443f-8c68-df401eab0354', a_id, $bp$What does the book compare a person disconnected from God to?$bp$, $bp$À quoi le livre compare-t-il une personne séparée de Dieu ?$bp$, 3, 1, 1),
      ('c20cb811-8e2e-463e-b097-f6d3e6648a51', a_id, $bp$What three things does the book say Genesis 1:26-28 shows about man's original design?$bp$, $bp$Quelles trois choses le livre dit-il que Genèse 1.26-28 montre du dessein original de l'homme ?$bp$, 4, 1, 1),
      ('3acc4d32-a590-4bff-98bf-0c0e7b6fdc98', a_id, $bp$How does the book say the serpent presented his lie to Eve?$bp$, $bp$Comment le livre dit-il que le serpent a présenté son mensonge à Ève ?$bp$, 5, 1, 1),
      ('3a5d178a-d3ce-4ab6-85f6-c17bbd4f7012', a_id, $bp$What does the book say repentance is, in relation to being disconnected from God?$bp$, $bp$Que dit le livre de la repentance par rapport à la séparation d'avec Dieu ?$bp$, 6, 1, 1),
      ('c366b4c0-4ec6-4daf-bbb7-66065381c31a', a_id, $bp$Which two words does the book give for repentance, and what do they mean?$bp$, $bp$Quels deux mots le livre donne-t-il pour la repentance, et que signifient-ils ?$bp$, 7, 1, 1),
      ('3b21db9a-fd65-4f31-aa3e-f565fecbaad1', a_id, $bp$Why does the book say Judas's regret was not true repentance?$bp$, $bp$Pourquoi le livre dit-il que le regret de Judas n'était pas une vraie repentance ?$bp$, 8, 1, 1),
      ('e9898375-4746-46ca-8b98-cbf5cd2fb8fd', a_id, $bp$What does the book say about Simon the Sorcerer asking Peter to pray for him?$bp$, $bp$Que dit le livre de Simon le magicien demandant à Pierre de prier pour lui ?$bp$, 9, 1, 1),
      ('50d0ea70-baf6-47aa-9b3a-6b3e6dd6f9d5', a_id, $bp$What picture does the book use to show how baptism makes repentance real and settled?$bp$, $bp$Quelle image le livre utilise-t-il pour montrer comment le baptême rend la repentance réelle et définitive ?$bp$, 10, 1, 1),
      ('7859f970-f0b7-44dc-b29c-7fb52f96c294', a_id, $bp$What does the Greek word baptidzo mean, according to the book?$bp$, $bp$Que signifie le mot grec baptidzo, selon le livre ?$bp$, 11, 1, 1),
      ('5c146ff6-5de5-4950-b32c-328bf8dbaab1', a_id, $bp$What three things does the book say happen at once in baptism?$bp$, $bp$Quelles trois choses le livre dit-il qui se produisent en même temps dans le baptême ?$bp$, 12, 1, 1),
      ('c4ccde82-10aa-4105-983f-c9d5cb1b7a36', a_id, $bp$According to the book, what pattern does Acts show about the timing of baptism?$bp$, $bp$Selon le livre, quel modèle les Actes montrent-ils quant au moment du baptême ?$bp$, 13, 1, 1),
      ('de27faf4-8ba4-4b85-93be-0b02e5ad8fb7', a_id, $bp$What picture does the book use to explain the three parts of the doorway?$bp$, $bp$Quelle image le livre utilise-t-il pour expliquer les trois parties de la porte d'entrée ?$bp$, 14, 1, 1),
      ('73aec376-ea04-429f-a162-0680d02b8358', a_id, $bp$How does the book describe the Holy Spirit?$bp$, $bp$Comment le livre décrit-il le Saint-Esprit ?$bp$, 15, 1, 1),
      ('90ec44ee-3e2c-4844-9cc9-929a83e6acb0', a_id, $bp$What does the book say changed about God's presence when the Holy Spirit came?$bp$, $bp$Que dit le livre du changement de la présence de Dieu quand le Saint-Esprit est venu ?$bp$, 16, 1, 1),
      ('c4ddf9bb-738d-4ed9-8211-8e181ca4dfae', a_id, $bp$At Samaria, why does the book say receiving the Holy Spirit was still its own distinct moment?$bp$, $bp$À Samarie, pourquoi le livre dit-il que recevoir le Saint-Esprit restait un moment distinct ?$bp$, 17, 1, 1),
      ('213ae5f3-7f3c-4516-b6b6-80015af976ed', a_id, $bp$According to the book, what is the difference between forgiveness and restoration?$bp$, $bp$Selon le livre, quelle est la différence entre le pardon et la restauration ?$bp$, 18, 1, 1),
      ('57746e2f-4cf4-47c7-b543-59a69da65b45', a_id, $bp$What two questions does the book say the next series of books will answer?$bp$, $bp$À quelles deux questions le livre dit-il que la prochaine série de livres répondra ?$bp$, 19, 1, 1),
      ('9cdf149e-212f-4c9f-99fb-77c4da53b86d', a_id, $bp$The book teaches that the ache people feel is mainly caused by their culture, money, or background.$bp$, $bp$Le livre enseigne que le malaise que ressentent les gens est surtout causé par leur culture, leur argent ou leur milieu.$bp$, 20, 1, 1),
      ('e61dc9b6-2bfc-408b-9dd8-35efd0d23f43', a_id, $bp$The book teaches that feeling sorry for sin is the same as repentance, so crying over sin is enough.$bp$, $bp$Le livre enseigne que regretter son péché est la même chose que se repentir, donc pleurer sur son péché suffit.$bp$, 21, 1, 1),
      ('4d29322f-146d-44de-a724-d043c34add60', a_id, $bp$The book teaches that baptism is an optional extra that can be done "someday".$bp$, $bp$Le livre enseigne que le baptême est une option supplémentaire qu'on peut faire « un jour ».$bp$, 22, 1, 1),
      ('83c7129d-9368-4e8d-8985-86819f552239', a_id, $bp$The book teaches that the Holy Spirit is only for advanced Christians, not for every believer.$bp$, $bp$Le livre enseigne que le Saint-Esprit est seulement pour les chrétiens avancés, pas pour chaque croyant.$bp$, 23, 1, 1),
      ('d1fec889-2710-4a89-9446-51ba6ff5a7b2', a_id, $bp$The book teaches that citizenship in the Kingdom is the destination of the journey.$bp$, $bp$Le livre enseigne que la citoyenneté du Royaume est la destination du voyage.$bp$, 24, 1, 1);
    INSERT INTO "Option" ("id", "questionId", "textEn", "textFr", "isCorrect", "order") VALUES
      ('a2ae29e5-b520-4995-af29-1774e62d29e1', 'bdc85a84-5f15-47d5-b16e-3b84fc6294c7', $bp$A promise made before others that a person will keep God's rules from now on$bp$, $bp$Une promesse faite devant les autres de garder désormais les règles de Dieu$bp$, FALSE, 0),
      ('12e190ed-94ce-4371-95b2-99ad3a580497', 'bdc85a84-5f15-47d5-b16e-3b84fc6294c7', $bp$A regular act of confession that keeps a believer in good standing with God$bp$, $bp$Un acte régulier de confession qui maintient le croyant en bonne position devant Dieu$bp$, FALSE, 1),
      ('ad5de558-d767-4618-9ae7-ce1dfa15fecb', 'bdc85a84-5f15-47d5-b16e-3b84fc6294c7', $bp$A deep feeling of remorse that leads a person to make better choices in life$bp$, $bp$Un profond sentiment de remords qui pousse une personne à faire de meilleurs choix dans la vie$bp$, FALSE, 2),
      ('496febdf-8bc8-4484-a28b-c3e0f2986f56', 'bdc85a84-5f15-47d5-b16e-3b84fc6294c7', $bp$A decisive change of mind and will that restores us to our original mandate$bp$, $bp$Un changement décisif d'esprit et de volonté qui nous rétablit dans notre mandat d'origine$bp$, TRUE, 3),
      ('29d49d7d-5bfb-4412-a816-af7b7b971f7e', '82684d39-ce7d-47bf-89b7-fdee6f3dbfa9', $bp$They are advanced topics, which are studied only after many years of experience$bp$, $bp$Ce sont des sujets avancés, qu'on n'étudie qu'après de nombreuses années d'expérience$bp$, FALSE, 0),
      ('e023ba75-9228-440d-bee4-55ec88d752d1', '82684d39-ce7d-47bf-89b7-fdee6f3dbfa9', $bp$They are optional extras, which add a little to the basic message of salvation$bp$, $bp$Ce sont des options supplémentaires, qui ajoutent un peu au message de base du salut$bp$, FALSE, 1),
      ('43b55bc5-51ce-4b33-b2f6-3d33c9f414a9', '82684d39-ce7d-47bf-89b7-fdee6f3dbfa9', $bp$They are old traditions, which have little connection with daily life today$bp$, $bp$Ce sont de vieilles traditions, qui ont peu de rapport avec la vie quotidienne d'aujourd'hui$bp$, FALSE, 2),
      ('c34b2ea8-6c7a-40b9-a2d1-d55e0d90e1d3', '82684d39-ce7d-47bf-89b7-fdee6f3dbfa9', $bp$They are the foundation on which all mature Christian understanding is built$bp$, $bp$Ce sont le fondement sur lequel toute compréhension chrétienne mûre est bâtie$bp$, TRUE, 3),
      ('19e66015-37bf-4c18-9d29-b144ca210e80', 'b32d5dd4-5fd4-41ce-b4ec-3ab899ee746c', $bp$A teacher in the classroom, who explains Bible facts to those who study hard enough$bp$, $bp$Un enseignant en classe, qui explique des faits bibliques à ceux qui étudient assez dur$bp$, FALSE, 0),
      ('99878b71-0edc-4be7-9464-979ce6fa9201', 'b32d5dd4-5fd4-41ce-b4ec-3ab899ee746c', $bp$The promised gift, the seal of ownership, and the source of power for witness and service$bp$, $bp$Le don promis, le sceau d'appartenance et la source de puissance pour le témoignage et le service$bp$, TRUE, 1),
      ('8a08c7c0-239a-4a3b-9b6c-de01145f495b', 'b32d5dd4-5fd4-41ce-b4ec-3ab899ee746c', $bp$A passing visitor, who gives the believer joy during times of prayer and worship services$bp$, $bp$Un visiteur de passage, qui donne de la joie au croyant pendant les temps de prière et d'adoration$bp$, FALSE, 2),
      ('a1060229-ba43-49fd-9b37-d0e1e77f00c2', 'b32d5dd4-5fd4-41ce-b4ec-3ab899ee746c', $bp$A reward, given to those who have lived a holy life for many years without failing$bp$, $bp$Une récompense, donnée à ceux qui ont vécu saintement pendant de nombreuses années sans faillir$bp$, FALSE, 3),
      ('602bab31-3f92-4686-9c0b-953f3a06669a', 'b3673a83-d719-443f-8c68-df401eab0354', $bp$A phone that looks fine but is not plugged in, and slowly runs out of power$bp$, $bp$Un téléphone qui paraît en bon état mais n'est pas branché, et qui perd lentement sa charge$bp$, TRUE, 0),
      ('35009a72-f96e-4d95-9de8-8c7e092ef92f', 'b3673a83-d719-443f-8c68-df401eab0354', $bp$A tree that looks fine but has no water, and slowly dries out from the roots$bp$, $bp$Un arbre qui paraît en bonne santé mais n'a pas d'eau, et qui se dessèche lentement par les racines$bp$, FALSE, 1),
      ('5e4a19d5-6d23-47f3-97da-c8f3f9637562', 'b3673a83-d719-443f-8c68-df401eab0354', $bp$A house that looks fine but has no foundation, and slowly begins to sink$bp$, $bp$Une maison qui paraît en bon état mais n'a pas de fondation, et qui commence lentement à s'enfoncer$bp$, FALSE, 2),
      ('ad23a18d-6241-42c7-9824-70221a309293', 'b3673a83-d719-443f-8c68-df401eab0354', $bp$A car that looks fine but has no driver, and slowly rolls off the road$bp$, $bp$Une voiture qui paraît en bon état mais n'a pas de conducteur, et qui dérape lentement hors de la route$bp$, FALSE, 3),
      ('67b31de6-e2ec-484c-9cdb-11130b274717', 'c20cb811-8e2e-463e-b097-f6d3e6648a51', $bp$Strength in the body, knowledge in the mind, and a home in the garden$bp$, $bp$La force du corps, la connaissance de l'esprit et une demeure dans le jardin$bp$, FALSE, 0),
      ('931cc9d2-f22c-49d8-bfed-9cc44dbcc0eb', 'c20cb811-8e2e-463e-b097-f6d3e6648a51', $bp$Rest in the garden, rule over the animals, and a name from God$bp$, $bp$Le repos dans le jardin, la domination sur les animaux et un nom donné par Dieu$bp$, FALSE, 1),
      ('75599a7f-f8d3-4f68-a04f-04993d8bad48', 'c20cb811-8e2e-463e-b097-f6d3e6648a51', $bp$Identity in God's image, closeness with God, and a job to do on earth$bp$, $bp$Une identité à l'image de Dieu, une proximité avec Dieu et un travail à accomplir sur la terre$bp$, TRUE, 2),
      ('ac2e3599-db6d-4b75-8778-ca72946350fa', 'c20cb811-8e2e-463e-b097-f6d3e6648a51', $bp$Wealth in the garden, wisdom from the tree, and a position over the angels$bp$, $bp$La richesse dans le jardin, la sagesse de l'arbre et une position au-dessus des anges$bp$, FALSE, 3),
      ('6496998a-dd2d-4e4e-ac7e-769622ae06d3', '3acc4d32-a590-4bff-98bf-0c0e7b6fdc98', $bp$As an upgrade or a promotion that would make her better, not as something evil$bp$, $bp$Comme une amélioration ou une promotion qui la rendrait meilleure, et non comme quelque chose de mauvais$bp$, TRUE, 0),
      ('c1423f79-4d36-4750-982f-d6a0d097304e', '3acc4d32-a590-4bff-98bf-0c0e7b6fdc98', $bp$As a harmless test, which God would forgive if she failed to pass it$bp$, $bp$Comme un test sans danger, que Dieu pardonnerait si elle ne le réussissait pas$bp$, FALSE, 1),
      ('cccdd1c4-a3d2-4e54-9e1f-0f9b7e41755d', '3acc4d32-a590-4bff-98bf-0c0e7b6fdc98', $bp$As a punishment, which she must accept if she wished to be forgiven for her pride$bp$, $bp$Comme une punition, qu'elle devait accepter si elle voulait être pardonnée de son orgueil$bp$, FALSE, 2),
      ('5207f4a4-26e4-4bd9-8324-f329b749fdb7', '3acc4d32-a590-4bff-98bf-0c0e7b6fdc98', $bp$As a command from God, which she must obey if she wished to stay in the garden$bp$, $bp$Comme un ordre de Dieu, auquel elle devait obéir si elle voulait rester dans le jardin$bp$, FALSE, 3),
      ('d762fe54-f108-4961-ab2e-d63d0ad5bd8e', '3a5d178a-d3ce-4ab6-85f6-c17bbd4f7012', $bp$It is the proof of the disconnection, which shows how far man has fallen from God$bp$, $bp$Elle est la preuve de la séparation, qui montre à quel point l'homme est tombé loin de Dieu$bp$, FALSE, 0),
      ('c92ba1ef-671d-421e-a515-c8a5ced066e0', '3a5d178a-d3ce-4ab6-85f6-c17bbd4f7012', $bp$It is the result of the disconnection, which grows stronger the longer a person waits$bp$, $bp$Elle est le résultat de la séparation, qui grandit plus la personne attend longtemps$bp$, FALSE, 1),
      ('92748142-5caf-46eb-bcee-b86356854f64', '3a5d178a-d3ce-4ab6-85f6-c17bbd4f7012', $bp$It is the fix for the disconnection, and the first move in getting reconnected$bp$, $bp$Elle est le remède à la séparation, et le premier mouvement pour être de nouveau relié$bp$, TRUE, 2),
      ('dc147deb-717d-4b32-8cf9-2db7951af312', '3a5d178a-d3ce-4ab6-85f6-c17bbd4f7012', $bp$It is the punishment for the disconnection, which God uses to teach man a lesson$bp$, $bp$Elle est la punition de la séparation, dont Dieu se sert pour donner une leçon à l'homme$bp$, FALSE, 3),
      ('2fd2fcef-7686-4e16-b350-0b1dc015a0ae', 'c366b4c0-4ec6-4daf-bbb7-66065381c31a', $bp$Agape, a deep love; and chesed, a loving kindness that never fails$bp$, $bp$Agapè, un amour profond ; et chesed, une bonté qui ne faillit jamais$bp$, FALSE, 0),
      ('1565bae3-5e35-486b-9f55-eb4ed85681a1', 'c366b4c0-4ec6-4daf-bbb7-66065381c31a', $bp$Pistis, a firm faith; and emunah, a trust that holds on without moving$bp$, $bp$Pistis, une foi ferme ; et emounah, une confiance qui tient sans bouger$bp$, FALSE, 1),
      ('ad3d5343-a438-4616-837e-1020487db195', 'c366b4c0-4ec6-4daf-bbb7-66065381c31a', $bp$Metanoia, a change of mind; and shuv, to turn around or return$bp$, $bp$Metanoia, un changement d'esprit ; et shouv, se retourner ou revenir$bp$, TRUE, 2),
      ('d5ae928f-cb26-433c-ab61-b6c2a82d61d3', 'c366b4c0-4ec6-4daf-bbb7-66065381c31a', $bp$Charis, a free grace; and shalom, a peace that restores what was broken$bp$, $bp$Charis, une grâce gratuite ; et shalom, une paix qui rétablit ce qui était brisé$bp$, FALSE, 3),
      ('09b43ffc-6dbf-4e6c-b23f-95e80b7d5ec7', '3b21db9a-fd65-4f31-aa3e-f565fecbaad1', $bp$He spoke the right words, but went back to his old ways when the pressure was gone$bp$, $bp$Il a dit les bonnes paroles, mais est retourné à ses anciennes habitudes quand la pression a disparu$bp$, FALSE, 0),
      ('f7b9cbbb-5f27-43db-a0e8-446e36a015ac', '3b21db9a-fd65-4f31-aa3e-f565fecbaad1', $bp$He gave back the money, but did not tell the elders the full truth of what he had done$bp$, $bp$Il a rendu l'argent, mais n'a pas dit aux anciens toute la vérité sur ce qu'il avait fait$bp$, FALSE, 1),
      ('2a8438c2-52c2-40b4-8398-f355245eeeae', '3b21db9a-fd65-4f31-aa3e-f565fecbaad1', $bp$He felt real regret, but never turned toward Jesus, and so it led to despair$bp$, $bp$Il a ressenti un vrai regret, mais ne s'est jamais tourné vers Jésus, et cela l'a mené au désespoir$bp$, TRUE, 2),
      ('b767fb62-1211-4ab7-9d35-20f5e3a49bea', '3b21db9a-fd65-4f31-aa3e-f565fecbaad1', $bp$He turned toward the other disciples, but they refused to forgive him for the betrayal$bp$, $bp$Il s'est tourné vers les autres disciples, mais ils ont refusé de lui pardonner la trahison$bp$, FALSE, 3),
      ('a62f5f94-57c0-401f-b5bd-a913b80cf5a8', 'e9898375-4746-46ca-8b98-cbf5cd2fb8fd', $bp$It shows that praying for someone else is the way a person is forgiven for sin$bp$, $bp$Cela montre que prier pour quelqu'un d'autre est le moyen d'être pardonné de son péché$bp$, FALSE, 0),
      ('0236f14d-46a9-4d58-8ea3-a93968ceb81b', 'e9898375-4746-46ca-8b98-cbf5cd2fb8fd', $bp$Nobody can make the turn for you; others can pray with you, but only you can repent$bp$, $bp$Personne ne peut faire le retournement à votre place ; d'autres peuvent prier avec vous, mais vous seul pouvez vous repentir$bp$, TRUE, 1),
      ('a5accdfb-a4d0-429c-82db-358f8f957472', 'e9898375-4746-46ca-8b98-cbf5cd2fb8fd', $bp$It shows that repentance is not needed when someone more spiritual prays on your behalf$bp$, $bp$Cela montre que la repentance n'est pas nécessaire quand une personne plus spirituelle prie à votre place$bp$, FALSE, 2),
      ('5cf8bb2f-00a5-4073-b267-1766b61d5fb3', 'e9898375-4746-46ca-8b98-cbf5cd2fb8fd', $bp$It shows that a leader's prayer is more powerful than the prayer of an ordinary believer$bp$, $bp$Cela montre que la prière d'un dirigeant est plus puissante que celle d'un croyant ordinaire$bp$, FALSE, 3),
      ('93af0849-79a3-42c7-901c-3817735695b2', '50d0ea70-baf6-47aa-9b3a-6b3e6dd6f9d5', $bp$A coronation day: the choice was made by the elders, but the crown makes the king official$bp$, $bp$Un jour de couronnement : le choix a été fait par les anciens, mais la couronne rend le roi officiel$bp$, FALSE, 0),
      ('976284d7-aa26-4ac8-94d2-21dd8f17cd90', '50d0ea70-baf6-47aa-9b3a-6b3e6dd6f9d5', $bp$A graduation day: the study was done in the mind, but the ceremony gives the final certificate$bp$, $bp$Un jour de remise de diplôme : l'étude a été faite dans l'esprit, mais la cérémonie donne le certificat final$bp$, FALSE, 1),
      ('4e8a7baf-e57d-4073-8f14-75a39dcf0718', '50d0ea70-baf6-47aa-9b3a-6b3e6dd6f9d5', $bp$A wedding day: the decision was made in the heart, but the public moment makes it official$bp$, $bp$Un jour de mariage : la décision a été prise dans le cœur, mais le moment public la rend officielle$bp$, TRUE, 2),
      ('44433a87-40ad-4ee5-856a-449289beaba4', '50d0ea70-baf6-47aa-9b3a-6b3e6dd6f9d5', $bp$A birthday: the life began long before, but the party celebrates how many years have passed$bp$, $bp$Un anniversaire : la vie a commencé bien avant, mais la fête célèbre le nombre d'années écoulées$bp$, FALSE, 3),
      ('302d2c5b-73e5-469e-bf96-706d07315dd7', '7859f970-f0b7-44dc-b29c-7fb52f96c294', $bp$To wash or cleanse: to remove the dirt from the body with running water$bp$, $bp$Laver ou purifier : enlever la saleté du corps avec de l'eau courante$bp$, FALSE, 0),
      ('8d01c294-ac4d-4a59-aa7a-554a41dbc67a', '7859f970-f0b7-44dc-b29c-7fb52f96c294', $bp$To bless or consecrate: to set a person apart for a holy purpose before God$bp$, $bp$Bénir ou consacrer : mettre une personne à part pour un but saint devant Dieu$bp$, FALSE, 1),
      ('e674cf05-6ea2-462f-aed0-1d4797f88b06', '7859f970-f0b7-44dc-b29c-7fb52f96c294', $bp$To dip or to immerse: to put fully under the water and bring back out$bp$, $bp$Plonger ou immerger : mettre entièrement sous l'eau et en ressortir$bp$, TRUE, 2),
      ('af9d51eb-6564-404e-bf2b-3aadeb79f3bc', '7859f970-f0b7-44dc-b29c-7fb52f96c294', $bp$To sprinkle or pour: to place a few drops of water on the head of the person$bp$, $bp$Asperger ou verser : mettre quelques gouttes d'eau sur la tête de la personne$bp$, FALSE, 3),
      ('07e85b9e-bd4d-4b9c-b4bb-69ae9985d45a', '5c146ff6-5de5-4950-b32c-328bf8dbaab1', $bp$A death of the old life, a burial of it, and a resurrection to the new$bp$, $bp$Une mort de l'ancienne vie, son ensevelissement et une résurrection à la nouvelle$bp$, TRUE, 0),
      ('b3b3ed6a-79ba-4618-8965-d06e667c7f8b', '5c146ff6-5de5-4950-b32c-328bf8dbaab1', $bp$A confession of sin, a cleansing of the body, and a promise to live better$bp$, $bp$Une confession du péché, une purification du corps et une promesse de mieux vivre$bp$, FALSE, 1),
      ('6f47c786-cdb2-4fa1-81de-14d8a1b75957', '5c146ff6-5de5-4950-b32c-328bf8dbaab1', $bp$A judgment of sin, a payment for it, and a covering by the blood of animals$bp$, $bp$Un jugement du péché, un paiement pour lui et une couverture par le sang des animaux$bp$, FALSE, 2),
      ('02482f38-8bd0-4108-8e48-9e06b143dbea', '5c146ff6-5de5-4950-b32c-328bf8dbaab1', $bp$A washing of the past, a blessing from the church, and a gift of the Spirit$bp$, $bp$Un lavage du passé, une bénédiction de l'Église et un don de l'Esprit$bp$, FALSE, 3),
      ('00bb1d27-8bed-4504-9e3c-51ee763adc85', 'c4ccde82-10aa-4105-983f-c9d5cb1b7a36', $bp$Nobody waited: believers were baptized right away, often the same day or hour$bp$, $bp$Personne n'a attendu : les croyants étaient baptisés tout de suite, souvent le jour ou l'heure même$bp$, TRUE, 0),
      ('155a1338-7a01-4429-b906-2ca1a455513a', 'c4ccde82-10aa-4105-983f-c9d5cb1b7a36', $bp$Believers waited until they had proved their change of life for a period of months$bp$, $bp$Les croyants attendaient d'avoir prouvé leur changement de vie pendant plusieurs mois$bp$, FALSE, 1),
      ('167a98ae-b781-4542-bdfc-5f0fed5e4618', 'c4ccde82-10aa-4105-983f-c9d5cb1b7a36', $bp$Believers waited until a church leader judged them to be ready to be baptized$bp$, $bp$Les croyants attendaient qu'un responsable d'Église juge qu'ils étaient prêts à être baptisés$bp$, FALSE, 2),
      ('8b46b2be-b93e-4461-86fd-7326e6afd375', 'c4ccde82-10aa-4105-983f-c9d5cb1b7a36', $bp$Believers waited for a season of teaching, which usually lasted about a year$bp$, $bp$Les croyants attendaient une période d'enseignement, qui durait généralement environ un an$bp$, FALSE, 3),
      ('2fbf272a-294e-4e47-9aee-9625e6af32f9', 'de27faf4-8ba4-4b85-93be-0b02e5ad8fb7', $bp$Repentance is drawing a map, baptism begins the journey, and the Spirit is the guide who leads$bp$, $bp$La repentance, c'est dessiner une carte, le baptême commence le voyage, et l'Esprit est le guide qui conduit$bp$, FALSE, 0),
      ('2de0fffe-37a0-465f-a69a-4a7b9d525b48', 'de27faf4-8ba4-4b85-93be-0b02e5ad8fb7', $bp$Repentance is planting a seed, baptism waters it, and the Spirit is the sun that makes it grow$bp$, $bp$La repentance, c'est planter une graine, le baptême l'arrose, et l'Esprit est le soleil qui la fait grandir$bp$, FALSE, 1),
      ('02442c67-7fba-48f0-8d00-e083f8746eea', 'de27faf4-8ba4-4b85-93be-0b02e5ad8fb7', $bp$Repentance is deciding to drive somewhere new, baptism starts the car, and the Spirit is the fuel$bp$, $bp$La repentance, c'est décider de conduire vers un endroit nouveau, le baptême démarre la voiture, et l'Esprit est le carburant$bp$, TRUE, 2),
      ('8d07b118-6d8f-420d-a628-7a9be510811e', 'de27faf4-8ba4-4b85-93be-0b02e5ad8fb7', $bp$Repentance is laying a foundation, baptism builds the walls, and the Spirit is the roof above$bp$, $bp$La repentance, c'est poser une fondation, le baptême bâtit les murs, et l'Esprit est le toit au-dessus$bp$, FALSE, 3),
      ('6d7cfbb6-b794-4716-9276-20760477e3c8', '73aec376-ea04-429f-a162-0680d02b8358', $bp$He is a force sent by God, which fills a person who has been trained to receive it$bp$, $bp$Il est une force envoyée par Dieu, qui remplit une personne formée pour la recevoir$bp$, FALSE, 0),
      ('c060c16e-a78c-4177-a3f2-071b338a617c', '73aec376-ea04-429f-a162-0680d02b8358', $bp$He is a feeling of peace, which comes to a person who has prayed for a long time$bp$, $bp$Il est un sentiment de paix, qui vient à une personne qui a prié pendant longtemps$bp$, FALSE, 1),
      ('548eb8f4-f87b-4c46-894e-ef966d5d3540', '73aec376-ea04-429f-a162-0680d02b8358', $bp$He is an angel sent by God, who stays beside a person who has lived a holy life$bp$, $bp$Il est un ange envoyé par Dieu, qui reste auprès d'une personne qui a vécu saintement$bp$, FALSE, 2),
      ('8060777a-4031-4697-9f00-53656f7aac35', '73aec376-ea04-429f-a162-0680d02b8358', $bp$He is God Himself, living inside a person who has repented and been baptized$bp$, $bp$Il est Dieu lui-même, qui habite en une personne qui s'est repentie et a été baptisée$bp$, TRUE, 3),
      ('997c575b-1012-41ff-b825-800a18c8c4f8', '90ec44ee-3e2c-4844-9cc9-929a83e6acb0', $bp$It moved from being sent to the nations to being limited to the church building alone$bp$, $bp$Elle est passée d'être envoyée aux nations à être limitée au seul bâtiment de l'Église$bp$, FALSE, 0),
      ('6fc4c755-f216-48ca-a770-7a684329de13', '90ec44ee-3e2c-4844-9cc9-929a83e6acb0', $bp$It moved from being inside people to being seen only in the great temple at Jerusalem$bp$, $bp$Elle est passée d'être à l'intérieur des gens à n'être vue que dans le grand temple de Jérusalem$bp$, FALSE, 1),
      ('68b1ecfa-3d87-42d5-844b-6a86b3e6a6f7', '90ec44ee-3e2c-4844-9cc9-929a83e6acb0', $bp$It moved from being hidden in Heaven to being visible in the sky to every person$bp$, $bp$Elle est passée d'être cachée au Ciel à être visible dans le ciel pour tout le monde$bp$, FALSE, 2),
      ('8c200fdf-a538-4955-815c-f7e01cd2d75e', '90ec44ee-3e2c-4844-9cc9-929a83e6acb0', $bp$It moved from being around people, in a temple or cloud, to living inside them$bp$, $bp$Elle est passée d'être autour des gens, dans un temple ou une nuée, à habiter en eux$bp$, TRUE, 3),
      ('3fc4c1e1-19de-473e-a6e5-41413046a3cb', 'c4ddf9bb-738d-4ed9-8211-8e181ca4dfae', $bp$The people had believed and been baptized, but they received Him later through prayer and laying on of hands$bp$, $bp$Les gens avaient cru et avaient été baptisés, mais ils l'ont reçu plus tard par la prière et l'imposition des mains$bp$, TRUE, 0),
      ('1ebfdae1-b767-4dc0-8cab-544d5dd89ef5', 'c4ddf9bb-738d-4ed9-8211-8e181ca4dfae', $bp$The people had believed but not been baptized, and they received Him when Philip preached to them$bp$, $bp$Les gens avaient cru mais n'avaient pas été baptisés, et ils l'ont reçu quand Philippe leur a prêché$bp$, FALSE, 1),
      ('d2ee09f3-af48-46ed-a182-510831ffaaa0', 'c4ddf9bb-738d-4ed9-8211-8e181ca4dfae', $bp$The people had been baptized, but they received Him only after waiting many months in prayer$bp$, $bp$Les gens avaient été baptisés, mais ils ne l'ont reçu qu'après avoir attendu de nombreux mois dans la prière$bp$, FALSE, 2),
      ('a6af82f0-9af8-4234-b16c-163d1092f74c', 'c4ddf9bb-738d-4ed9-8211-8e181ca4dfae', $bp$The people had been baptized and received Him at the same moment, as they came up out of the water$bp$, $bp$Les gens avaient été baptisés et l'ont reçu au même moment, en sortant de l'eau$bp$, FALSE, 3),
      ('71d9e434-c7bd-452b-a5c0-de7614c2aab9', '213ae5f3-7f3c-4516-b6b6-80015af976ed', $bp$Forgiveness deals with the past, while restoration deals with the future$bp$, $bp$Le pardon concerne le passé, tandis que la restauration concerne l'avenir$bp$, TRUE, 0),
      ('457b9c41-e3b9-4e32-b1e2-ea0772a6a9da', '213ae5f3-7f3c-4516-b6b6-80015af976ed', $bp$Forgiveness happens in Heaven, while restoration happens only after we die$bp$, $bp$Le pardon se fait au Ciel, tandis que la restauration n'a lieu qu'après notre mort$bp$, FALSE, 1),
      ('c9295898-7ef1-4a51-910e-42d7dca48811', '213ae5f3-7f3c-4516-b6b6-80015af976ed', $bp$Forgiveness is given by God, while restoration must be earned by good works$bp$, $bp$Le pardon est donné par Dieu, tandis que la restauration doit être gagnée par de bonnes œuvres$bp$, FALSE, 2),
      ('19064cba-2bca-469b-b8e2-acfce60b9e05', '213ae5f3-7f3c-4516-b6b6-80015af976ed', $bp$Forgiveness deals with the body, while restoration deals with the soul and spirit$bp$, $bp$Le pardon concerne le corps, tandis que la restauration concerne l'âme et l'esprit$bp$, FALSE, 3),
      ('2ca78d03-5a8d-4e79-a53d-17629cd871d5', '57746e2f-4cf4-47c7-b543-59a69da65b45', $bp$Who is my enemy, and what weapons do I need to win the war against him?$bp$, $bp$Qui est mon ennemi, et de quelles armes ai-je besoin pour gagner la guerre contre lui ?$bp$, FALSE, 0),
      ('f85b1a64-75c2-4946-a3ea-5fe058bafdd6', '57746e2f-4cf4-47c7-b543-59a69da65b45', $bp$Why did I fall, and how can I be sure that I will never fall again?$bp$, $bp$Pourquoi suis-je tombé, et comment être sûr que je ne tomberai plus jamais ?$bp$, FALSE, 1),
      ('581f6a70-d67c-462c-8e4b-df92f92a4523', '57746e2f-4cf4-47c7-b543-59a69da65b45', $bp$What do I have as a citizen, and how do I use it in daily life?$bp$, $bp$Qu'ai-je en tant que citoyen, et comment l'utiliser dans la vie quotidienne ?$bp$, TRUE, 2),
      ('8b56eb21-3c51-4dc8-bf55-02a80802aa24', '57746e2f-4cf4-47c7-b543-59a69da65b45', $bp$Where do I serve, and how do I find the right ministry in the church?$bp$, $bp$Où dois-je servir, et comment trouver le bon ministère dans l'Église ?$bp$, FALSE, 3),
      ('8153c672-dd20-411a-bcc7-3fdfc1aa8844', '9cdf149e-212f-4c9f-99fb-77c4da53b86d', $bp$TRUE$bp$, $bp$VRAI$bp$, FALSE, 0),
      ('a10d1fdc-3098-4aa8-b4c6-ee12506a7e02', '9cdf149e-212f-4c9f-99fb-77c4da53b86d', $bp$FALSE$bp$, $bp$FAUX$bp$, TRUE, 1),
      ('d622e44c-7e24-4fde-bc5f-9cede6c6e96c', 'e61dc9b6-2bfc-408b-9dd8-35efd0d23f43', $bp$TRUE$bp$, $bp$VRAI$bp$, FALSE, 0),
      ('57f6324e-6397-4dbc-ba3c-d24072801702', 'e61dc9b6-2bfc-408b-9dd8-35efd0d23f43', $bp$FALSE$bp$, $bp$FAUX$bp$, TRUE, 1),
      ('70c08e22-9bd1-4cfc-925c-52beb21d77e0', '4d29322f-146d-44de-a724-d043c34add60', $bp$TRUE$bp$, $bp$VRAI$bp$, FALSE, 0),
      ('52c31347-1e6d-40f2-86ec-6fdd14919cc1', '4d29322f-146d-44de-a724-d043c34add60', $bp$FALSE$bp$, $bp$FAUX$bp$, TRUE, 1),
      ('c7b648d3-d650-4b65-b29e-ca0560549408', '83c7129d-9368-4e8d-8985-86819f552239', $bp$TRUE$bp$, $bp$VRAI$bp$, FALSE, 0),
      ('f4b519ba-9c7d-4082-98e1-3f921d4a0c35', '83c7129d-9368-4e8d-8985-86819f552239', $bp$FALSE$bp$, $bp$FAUX$bp$, TRUE, 1),
      ('aca8253d-df3e-4685-9a90-f1738517d728', 'd1fec889-2710-4a89-9446-51ba6ff5a7b2', $bp$TRUE$bp$, $bp$VRAI$bp$, FALSE, 0),
      ('00d3666b-b9df-4ceb-a60b-076bc068b0ba', 'd1fec889-2710-4a89-9446-51ba6ff5a7b2', $bp$FALSE$bp$, $bp$FAUX$bp$, TRUE, 1);
    INSERT INTO "PersonalQuestion" ("id", "assessmentId", "setNumber", "order", "kind", "textEn", "textFr", "bodyEn", "bodyFr", "guideEn", "guideFr", "required", "flagUnlessNone", "affectsStatus") VALUES
      ('2a1e729c-a6b9-4057-8903-8b729ddb4324', a_id, 1, 0, 'CHOICE', $bp$Chapter Two says repentance is a change of mind that leads to a change of direction. Have you turned from your old way of living and given your life to Jesus Christ?$bp$, $bp$Le chapitre deux dit que la repentance est un changement d'esprit qui mène à un changement de direction. Vous êtes-vous détourné de votre ancienne manière de vivre et avez-vous donné votre vie à Jésus-Christ ?$bp$, NULL, NULL, $bp$Yes: ask what changed. Not yet, on the way, or not sure: explain that repentance is a decision, not a feeling (Chapter Two). Invite them to pray the Prayer of Repentance from Chapter Two with you.$bp$, $bp$Oui : demandez ce qui a changé. Pas encore, en chemin ou pas sûr : expliquez que la repentance est une décision, pas un sentiment (chapitre deux). Invitez la personne à prier avec vous la prière de repentance du chapitre deux.$bp$, TRUE, FALSE, TRUE),
      ('d4224a85-3528-4d34-8978-a446d07e138f', a_id, 1, 1, 'CHOICE', $bp$Have you been baptized in water by immersion, going fully under the water and coming back up, after you believed in Jesus?$bp$, $bp$Avez-vous été baptisé d'eau par immersion, en descendant entièrement sous l'eau puis en ressortant, après avoir cru en Jésus ?$bp$, NULL, NULL, $bp$Yes, fully immersed after believing: this is the book's pattern (baptidzo means to immerse; Romans 6:3-4). Sprinkled or baptized before believing: gently explain that the book teaches believer's baptism by immersion, and arrange it. Not yet: do not wait; arrange it as soon as possible, as every example in Acts did.$bp$, $bp$Oui, immergé après avoir cru : c'est le modèle du livre (baptidzo signifie immerger ; Romains 6.3-4). Aspergé ou baptisé avant de croire : expliquez avec douceur que le livre enseigne le baptême du croyant par immersion, et organisez-le. Pas encore : n'attendez pas ; organisez-le dès que possible, comme tous les exemples des Actes.$bp$, TRUE, FALSE, FALSE),
      ('10645eef-900c-416d-9953-24fd4db45227', a_id, 1, 2, 'TEXT', $bp$If yes, when and where were you baptized, and who baptized you?$bp$, $bp$Si oui, quand et où avez-vous été baptisé, et qui vous a baptisé ?$bp$, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE),
      ('1df0ed01-cb57-42c3-8112-12f739fcb2fc', a_id, 1, 3, 'CHOICE', $bp$Have you received the Holy Spirit, with the evidence of speaking in other tongues, as in Acts 2, 10 and 19?$bp$, $bp$Avez-vous reçu le Saint-Esprit, avec pour preuve de parler en d'autres langues, comme en Actes 2, 10 et 19 ?$bp$, NULL, NULL, $bp$Yes with tongues: celebrate. Have the Spirit but no tongues, not yet, or need explaining: teach Luke 11:13 (a gift received by asking), and the examples at Pentecost, Cornelius, and Ephesus where they spoke in tongues. Offer to pray with laying on of hands (Acts 8:17; 19:6).$bp$, $bp$Oui avec les langues : réjouissez-vous. A l'Esprit mais pas de langues, pas encore, ou besoin d'explication : enseignez Luc 11.13 (un don reçu en demandant) et les exemples de la Pentecôte, de Corneille et d'Éphèse où ils ont parlé en langues. Proposez de prier avec imposition des mains (Actes 8.17 ; 19.6).$bp$, TRUE, FALSE, FALSE),
      ('20e57283-5af7-4647-95c3-bd6a7c74324f', a_id, 1, 4, 'TEXT', $bp$If yes, when and how did you receive Him?$bp$, $bp$Si oui, quand et comment l'avez-vous reçu ?$bp$, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE),
      ('8ed2fd95-bf4b-4433-8a91-ace3cf0276be', a_id, 1, 5, 'TEXT', $bp$Chapter Three says the old life is buried and a new life begins. What has changed in your life since you made your decision for Christ?$bp$, $bp$Le chapitre trois dit que l'ancienne vie est ensevelie et qu'une nouvelle vie commence. Qu'est-ce qui a changé dans votre vie depuis que vous avez pris votre décision pour Christ ?$bp$, NULL, NULL, $bp$Look for real change: new desire for the Word, freedom, changed habits. If "nothing yet", treat it as an open door for a conversation.$bp$, $bp$Cherchez un vrai changement : nouveau désir de la Parole, liberté, habitudes changées. Si « rien encore », voyez-y une porte ouverte pour une conversation.$bp$, TRUE, FALSE, FALSE),
      ('31f7d471-5159-49bf-bb05-56ccdff510f7', a_id, 1, 6, 'TEXT', $bp$What is the one thing, if any, that is holding you back from taking the next step in the doorway (repentance, baptism, or the Holy Spirit)? If nothing, write "nothing".$bp$, $bp$Quelle est la seule chose, s'il y en a une, qui vous retient de franchir la prochaine étape de la porte d'entrée (repentance, baptême ou Saint-Esprit) ? S'il n'y a rien, écrivez « rien ».$bp$, NULL, NULL, $bp$Read this with care and pray over it. Name the barrier gently, and answer it from the book. Note them for follow-up.$bp$, $bp$Lisez avec soin et priez à ce sujet. Nommez doucement l'obstacle et répondez-y à partir du livre. Notez la personne pour un suivi.$bp$, TRUE, TRUE, FALSE),
      ('c51c78a2-1907-4ac2-a660-45a89d715cf1', a_id, 1, 7, 'CHOICE', $bp$My Confession of Faith$bp$, $bp$Ma confession de foi$bp$, $bp$Read this confession slowly, and think about every word. If it is the true desire of your heart, tick "I agree". If you are not ready, tick "I do not agree". You will not be judged for being honest.
    INSERT INTO "PersonalOption" ("id", "questionId", "order", "textEn", "textFr", "signal") VALUES
      ('37476322-c500-4e9e-a8db-abd019d61385', '2a1e729c-a6b9-4057-8903-8b729ddb4324', 0, $bp$Yes, I have turned, and I have received Jesus as my Lord and Saviour$bp$, $bp$Oui, je me suis détourné, et j'ai reçu Jésus comme mon Seigneur et Sauveur$bp$, 'POSITIVE'),
      ('90a2f13a-3ce3-4563-b260-819f6c1ce66c', '2a1e729c-a6b9-4057-8903-8b729ddb4324', 1, $bp$I am on the way, but I have not fully turned yet$bp$, $bp$Je suis en chemin, mais je ne me suis pas encore pleinement détourné$bp$, 'NEEDS_TALK'),
      ('a006ba3f-03d4-4e93-879b-d1bede94035a', '2a1e729c-a6b9-4057-8903-8b729ddb4324', 2, $bp$Not yet$bp$, $bp$Pas encore$bp$, 'NEEDS_TALK'),
      ('ce1033b8-8e7f-4a85-ace0-9ec1d8db686c', '2a1e729c-a6b9-4057-8903-8b729ddb4324', 3, $bp$I am not sure what this means for me$bp$, $bp$Je ne suis pas sûr de ce que cela signifie pour moi$bp$, 'NEEDS_TALK'),
      ('01680924-e0f9-46bf-aad2-facbddb5ba47', 'd4224a85-3528-4d34-8978-a446d07e138f', 0, $bp$Yes, I was fully immersed in water after I believed$bp$, $bp$Oui, j'ai été entièrement immergé dans l'eau après avoir cru$bp$, 'POSITIVE'),
      ('8edf0206-e10a-4ac5-ba3f-bea3dcaa1b75', 'd4224a85-3528-4d34-8978-a446d07e138f', 1, $bp$Yes, but I was sprinkled, or I was baptized before I believed$bp$, $bp$Oui, mais j'ai été aspergé, ou j'ai été baptisé avant de croire$bp$, 'NEEDS_TALK'),
      ('3018e9a8-3d6f-41c8-914f-8e347fb8458f', 'd4224a85-3528-4d34-8978-a446d07e138f', 2, $bp$No, I have not been baptized yet, but I want to be baptized now$bp$, $bp$Non, je n'ai pas encore été baptisé, mais je veux être baptisé maintenant$bp$, 'NEEDS_TALK'),
      ('1ef9d6a3-0522-4194-89f9-ec72a01a24c5', 'd4224a85-3528-4d34-8978-a446d07e138f', 3, $bp$No, I am not sure that baptism is needed$bp$, $bp$Non, je ne suis pas sûr que le baptême soit nécessaire$bp$, 'NEEDS_TALK'),
      ('d76e1b24-91f6-4f8e-8f67-9fbdecca43b3', '1df0ed01-cb57-42c3-8112-12f739fcb2fc', 0, $bp$Yes, I have received the Holy Spirit, and I speak in other tongues$bp$, $bp$Oui, j'ai reçu le Saint-Esprit, et je parle en d'autres langues$bp$, 'POSITIVE'),
      ('ce652489-a28c-4cf9-a22e-40b259a6dd99', '1df0ed01-cb57-42c3-8112-12f739fcb2fc', 1, $bp$I believe I have the Holy Spirit, but I have not yet spoken in other tongues$bp$, $bp$Je crois avoir le Saint-Esprit, mais je n'ai pas encore parlé en d'autres langues$bp$, 'NEEDS_TALK'),
      ('22c59316-02f5-41f6-8c73-56f08c2ccbdb', '1df0ed01-cb57-42c3-8112-12f739fcb2fc', 2, $bp$Not yet, but I want to receive Him now$bp$, $bp$Pas encore, mais je veux le recevoir maintenant$bp$, 'NEEDS_TALK'),
      ('7212adc3-ecfb-4e6d-83e1-142e9297f17f', '1df0ed01-cb57-42c3-8112-12f739fcb2fc', 3, $bp$I need someone to explain this to me$bp$, $bp$J'ai besoin que quelqu'un m'explique cela$bp$, 'NEEDS_TALK'),
      ('5eedd653-6b33-46bd-b3c5-5228089e0989', 'c51c78a2-1907-4ac2-a660-45a89d715cf1', 0, $bp$I agree with this confession, and I make it my own$bp$, $bp$Je suis d'accord avec cette confession, et je la fais mienne$bp$, 'POSITIVE'),
      ('c56c7824-36d9-4ad2-b4d9-67d67fff52da', 'c51c78a2-1907-4ac2-a660-45a89d715cf1', 1, $bp$I do not agree with this confession$bp$, $bp$Je ne suis pas d'accord avec cette confession$bp$, 'NEEDS_TALK');
    INSERT INTO "Question" ("id", "assessmentId", "textEn", "textFr", "order", "points", "setNumber") VALUES
      ('524d1e9b-7aa0-4bf4-a531-923ca8cf6e5f', a_id, $bp$What does the Author's Word say baptism is?$bp$, $bp$Que dit le Mot de l'auteur du baptême ?$bp$, 0, 1, 2),
      ('5effd9bf-e521-463c-9852-fe6ec03e5bfd', a_id, $bp$According to the Author's Word, what is the purpose of authority in God's Kingdom?$bp$, $bp$Selon le Mot de l'auteur, quel est le but de l'autorité dans le Royaume de Dieu ?$bp$, 1, 1, 2),
      ('83320c16-33d6-4983-91a1-c91b9f8d1357', a_id, $bp$How does the Introduction describe the believer's calling regarding these truths?$bp$, $bp$Comment l'Introduction décrit-elle l'appel du croyant à l'égard de ces vérités ?$bp$, 2, 1, 2),
      ('37ee820c-d15e-47ce-995d-54cd75e88484', a_id, $bp$What does the book say man was created inside of, rather than having to go looking for it?$bp$, $bp$Dans quoi le livre dit-il que l'homme a été créé, au lieu d'avoir à le chercher ?$bp$, 3, 1, 2),
      ('307e0862-40ae-42bf-87c9-e6e58c3d8ca8', a_id, $bp$What does the book say changed in the garden when Adam and Eve sinned?$bp$, $bp$Que dit le livre qui a changé dans le jardin quand Adam et Ève ont péché ?$bp$, 4, 1, 2),
      ('48ab320a-0112-4d98-9c62-a877ecfc0158', a_id, $bp$Why does the book say fixes aimed only at the symptoms rarely last?$bp$, $bp$Pourquoi le livre dit-il que les remèdes qui visent seulement les symptômes durent rarement ?$bp$, 5, 1, 2),
      ('d3a057e3-f742-4c5c-aebb-86b119bcf3da', a_id, $bp$What does the book say Jesus was telling people when He said "Repent"?$bp$, $bp$Que dit le livre que Jésus disait aux gens quand il a dit « Repentez-vous » ?$bp$, 6, 1, 2),
      ('57f01c51-a746-4cec-8df7-9c0d28f3280f', a_id, $bp$What does the book teach from the story of the two sons sent to work in the field?$bp$, $bp$Qu'enseigne le livre à partir de l'histoire des deux fils envoyés travailler au champ ?$bp$, 7, 1, 2),
      ('1e45b38c-7fa7-47cf-9284-e4be3686659c', a_id, $bp$Why does the book say Pharaoh's repentance was false?$bp$, $bp$Pourquoi le livre dit-il que la repentance de Pharaon était fausse ?$bp$, 8, 1, 2),
      ('749382c9-66c9-4f59-ad07-33897d59554f', a_id, $bp$What does the book say Zacchaeus's repentance shows?$bp$, $bp$Que montre, selon le livre, la repentance de Zachée ?$bp$, 9, 1, 2),
      ('243817d3-f268-4427-a894-c88b93dd3b22', a_id, $bp$What does the book say about baptism and the old life?$bp$, $bp$Que dit le livre du baptême et de l'ancienne vie ?$bp$, 10, 1, 2),
      ('6ec2f5e6-b8a1-4172-b143-885f902dbfb4', a_id, $bp$What order does the book point out in Jesus' own baptism?$bp$, $bp$Quel ordre le livre relève-t-il dans le baptême de Jésus lui-même ?$bp$, 11, 1, 2),
      ('d61d4973-7c9e-47e3-b4fd-ad2e87cdec8a', a_id, $bp$What does the book say about who should be baptized?$bp$, $bp$Que dit le livre de ceux qui doivent être baptisés ?$bp$, 12, 1, 2),
      ('f1ff5825-dc64-4db9-98be-81bfcb7915db', a_id, $bp$How does the book explain the two baptism formulas, "Father, Son, and Holy Spirit" and "the name of Jesus"?$bp$, $bp$Comment le livre explique-t-il les deux formules de baptême, « Père, Fils et Saint-Esprit » et « au nom de Jésus » ?$bp$, 13, 1, 2),
      ('592f7529-845a-48e9-a512-deea904fff31', a_id, $bp$What does the book say the Holy Spirit's arrival looks like in the Acts examples?$bp$, $bp$Que dit le livre de l'arrivée du Saint-Esprit dans les exemples des Actes ?$bp$, 14, 1, 2),
      ('7c860d99-48a2-499c-a9f4-c99b7a24c396', a_id, $bp$Where, in the book's examples, did the Spirit come before baptism had even taken place?$bp$, $bp$Où, dans les exemples du livre, l'Esprit est-il venu avant même que le baptême ait eu lieu ?$bp$, 15, 1, 2),
      ('163bd6ee-4ecf-4f21-a3e8-891906b4f22b', a_id, $bp$Which list of ongoing results of the Spirit's coming does the book give?$bp$, $bp$Quelle liste de résultats durables de la venue de l'Esprit le livre donne-t-il ?$bp$, 16, 1, 2),
      ('b0aeec06-87c8-4d14-9645-13c41986d3db', a_id, $bp$What does the book say about receiving the Spirit, using Luke 11:13?$bp$, $bp$Que dit le livre de la réception de l'Esprit, à partir de Luc 11.13 ?$bp$, 17, 1, 2),
      ('951e37a5-f4ef-41cb-9031-f8ee73709689', a_id, $bp$What does the book say is the believer's identity after coming through the door?$bp$, $bp$Que dit le livre de l'identité du croyant après avoir franchi la porte ?$bp$, 18, 1, 2),
      ('0c3205ab-bc04-42e6-bdec-b13a49974c62', a_id, $bp$According to the book, what does an ambassador do?$bp$, $bp$Selon le livre, que fait un ambassadeur ?$bp$, 19, 1, 2),
      ('e1344c9a-077b-4d96-b0f1-1eeb09e55ebc', a_id, $bp$The book teaches that Solomon, with all his resources, found that the ache can only be fixed by reconnecting with God.$bp$, $bp$Le livre enseigne que Salomon, avec toutes ses ressources, a découvert que le malaise ne peut être guéri qu'en se reconnectant à Dieu.$bp$, 20, 1, 2),
      ('9cb25a94-ad88-4410-8d60-61dfbd050263', a_id, $bp$The book teaches that repentance is you earning forgiveness through your own effort.$bp$, $bp$Le livre enseigne que la repentance, c'est mériter le pardon par son propre effort.$bp$, 21, 1, 2),
      ('ee4074ad-e6e6-4c8d-8f31-4a4ce1593c48', a_id, $bp$The book teaches that the Ethiopian official was baptized the moment he believed.$bp$, $bp$Le livre enseigne que le dignitaire éthiopien a été baptisé au moment même où il a cru.$bp$, 22, 1, 2),
      ('473bb196-93d2-4de1-8262-2a4c37772971', a_id, $bp$The book teaches that the Holy Spirit always came in the same order, only after baptism.$bp$, $bp$Le livre enseigne que le Saint-Esprit est toujours venu dans le même ordre, seulement après le baptême.$bp$, 23, 1, 2),
      ('957a9288-15c9-4a92-af4c-d642f74e6720', a_id, $bp$The book teaches that old things such as old identity and shame have passed away completely, not just been put on hold.$bp$, $bp$Le livre enseigne que les choses anciennes, comme l'ancienne identité et la honte, ont complètement disparu, et ne sont pas seulement mises en attente.$bp$, 24, 1, 2);
    INSERT INTO "Option" ("id", "questionId", "textEn", "textFr", "isCorrect", "order") VALUES
      ('b6c31c71-c0fb-45bf-9f9f-a6174efa3690', '524d1e9b-7aa0-4bf4-a531-923ca8cf6e5f', $bp$A cleansing ritual that removes the sins a person committed before he believed in Christ$bp$, $bp$Un rite de purification qui enlève les péchés commis par une personne avant qu'elle croie en Christ$bp$, FALSE, 0),
      ('aa37c462-4a08-4b34-a282-d98997abcb03', '524d1e9b-7aa0-4bf4-a531-923ca8cf6e5f', $bp$A private act of devotion between the believer and God, which others do not need to see$bp$, $bp$Un acte privé de dévotion entre le croyant et Dieu, que les autres n'ont pas besoin de voir$bp$, FALSE, 1),
      ('8a944070-e1aa-48fd-9895-22831495c65e', '524d1e9b-7aa0-4bf4-a531-923ca8cf6e5f', $bp$The public enactment of union with Christ's death, burial, and resurrection, not an empty ritual$bp$, $bp$La représentation publique de l'union avec la mort, l'ensevelissement et la résurrection de Christ, et non un rite vide$bp$, TRUE, 2),
      ('c3fd2c79-9c63-4b59-9af6-3ea70c8870ca', '524d1e9b-7aa0-4bf4-a531-923ca8cf6e5f', $bp$A church ceremony that gives a person a name and a place on the membership list of the congregation$bp$, $bp$Une cérémonie d'Église qui donne à une personne un nom et une place sur la liste des membres de l'assemblée$bp$, FALSE, 3),
      ('4d42c6ce-bd8b-4612-b527-09e7d72c516a', '5effd9bf-e521-463c-9852-fe6ec03e5bfd', $bp$It is given so that believers may be protected from every trouble that this world brings upon them$bp$, $bp$Elle est donnée pour que les croyants soient protégés de tous les ennuis que ce monde leur apporte$bp$, FALSE, 0),
      ('5b357f7d-5aaf-4626-a529-fbc671e8ac15', '5effd9bf-e521-463c-9852-fe6ec03e5bfd', $bp$It is given so that the church may grow large and become strong among the nations$bp$, $bp$Elle est donnée pour que l'Église grandisse en nombre et devienne forte parmi les nations$bp$, FALSE, 1),
      ('6f54d8b6-20f0-4c74-8a51-5aa308da9905', '5effd9bf-e521-463c-9852-fe6ec03e5bfd', $bp$It is given so that we may serve, heal, free others, and bring order where there is chaos$bp$, $bp$Elle est donnée pour que nous servions, guérissions, libérions les autres et mettions de l'ordre là où règne le chaos$bp$, TRUE, 2),
      ('164479ba-2603-4112-8b53-ebca1e39d836', '5effd9bf-e521-463c-9852-fe6ec03e5bfd', $bp$It is given so that leaders may be respected, obeyed, and honoured by those they lead$bp$, $bp$Elle est donnée pour que les dirigeants soient respectés, obéis et honorés par ceux qu'ils dirigent$bp$, FALSE, 3),
      ('9e927d1f-fbb1-4135-be07-c341727f414a', '83320c16-33d6-4983-91a1-c91b9f8d1357', $bp$To pass them on to others, so that the church may grow in numbers each year$bp$, $bp$Les transmettre aux autres, pour que l'Église grandisse en nombre chaque année$bp$, FALSE, 0),
      ('be259dac-acfa-4ce6-823e-d9584f85e319', '83320c16-33d6-4983-91a1-c91b9f8d1357', $bp$To keep them as personal beliefs, so as to avoid causing trouble in daily life$bp$, $bp$Les garder comme des croyances personnelles, afin d'éviter des ennuis dans la vie quotidienne$bp$, FALSE, 1),
      ('8c2bd96c-a85b-4113-aeef-46e574394d79', '83320c16-33d6-4983-91a1-c91b9f8d1357', $bp$To study them deeply, so as to become skilled teachers who can win every argument$bp$, $bp$Les étudier à fond, pour devenir des enseignants habiles capables de gagner toutes les discussions$bp$, FALSE, 2),
      ('80026578-1b15-4890-bca8-218682a9f747', '83320c16-33d6-4983-91a1-c91b9f8d1357', $bp$To embody a transformed life governed by Kingdom principles, not merely agree with ideas$bp$, $bp$Incarner une vie transformée, gouvernée par les principes du Royaume, et pas seulement être d'accord avec des idées$bp$, TRUE, 3),
      ('b75176da-6255-47fa-9f5e-b3f56e01c439', '37ee820c-d15e-47ce-995d-54cd75e88484', $bp$A Kingdom already in place, where he served as God's representative, ruling on His behalf$bp$, $bp$Un Royaume déjà en place, où il servait de représentant de Dieu, gouvernant en son nom$bp$, TRUE, 0),
      ('d2221d92-cfc7-43a8-ab20-86b222b57df5', '37ee820c-d15e-47ce-995d-54cd75e88484', $bp$A nation, which he had to build and defend until it had grown large enough to rule$bp$, $bp$Une nation, qu'il devait bâtir et défendre jusqu'à ce qu'elle soit assez grande pour régner$bp$, FALSE, 1),
      ('6d08b906-cd46-42dd-b3b9-4eaeba7033d0', '37ee820c-d15e-47ce-995d-54cd75e88484', $bp$A temple, where he had to serve as a priest until God gave him the authority to rule$bp$, $bp$Un temple, où il devait servir comme prêtre jusqu'à ce que Dieu lui donne l'autorité de régner$bp$, FALSE, 2),
      ('7757fc7a-b6a8-4c84-832d-60c0970410c4', '37ee820c-d15e-47ce-995d-54cd75e88484', $bp$A garden, which he had to tend and protect until he had earned the right to rule over it completely$bp$, $bp$Un jardin, qu'il devait cultiver et protéger jusqu'à avoir mérité le droit de régner entièrement sur lui$bp$, FALSE, 3),
      ('10cbd26e-da39-4199-8bfb-f7099048dfca', '307e0862-40ae-42bf-87c9-e6e58c3d8ca8', $bp$Not their connection, but where they were, since God moved them out of His presence and into the wilderness$bp$, $bp$Non pas leur lien, mais leur lieu, puisque Dieu les a fait sortir de sa présence pour les mettre dans le désert$bp$, FALSE, 0),
      ('949a734a-67f7-4db4-8e3e-577cab6bdb54', '307e0862-40ae-42bf-87c9-e6e58c3d8ca8', $bp$Not their job, but their rewards, since God took away the fruit of all their labour$bp$, $bp$Non pas leur travail, mais leurs récompenses, puisque Dieu a retiré le fruit de tout leur labeur$bp$, FALSE, 1),
      ('650a4814-db56-4034-8221-fa192122b0da', '307e0862-40ae-42bf-87c9-e6e58c3d8ca8', $bp$Not where they were, but their connection: the power source behind their rule was cut off$bp$, $bp$Non pas leur lieu, mais leur lien : la source de puissance derrière leur règne a été coupée$bp$, TRUE, 2),
      ('1a3b2d15-5130-4fbc-8db0-c54342ca988c', '307e0862-40ae-42bf-87c9-e6e58c3d8ca8', $bp$Not their identity, but their strength, as their bodies grew weak and began to age$bp$, $bp$Non pas leur identité, mais leur force, car leur corps est devenu faible et a commencé à vieillir$bp$, FALSE, 3),
      ('e0963c89-8df6-4a4c-a672-1d361ada0ea0', '48ab320a-0112-4d98-9c62-a877ecfc0158', $bp$Symptoms disappear on their own with time, so the fixes are never really needed at all$bp$, $bp$Les symptômes disparaissent d'eux-mêmes avec le temps, donc les remèdes ne sont jamais vraiment nécessaires$bp$, FALSE, 0),
      ('13eb530d-33b0-4f94-bf86-020b225817e1', '48ab320a-0112-4d98-9c62-a877ecfc0158', $bp$Symptoms are caused by the failures of the leaders, who do not apply the fixes well$bp$, $bp$Les symptômes sont causés par les échecs des dirigeants, qui n'appliquent pas bien les remèdes$bp$, FALSE, 1),
      ('3a652b19-4ff2-443e-aaab-bea99e95d77e', '48ab320a-0112-4d98-9c62-a877ecfc0158', $bp$Money troubles, fear, and confusion all grow out of the root problem, disconnection from God$bp$, $bp$Les problèmes d'argent, la peur et la confusion naissent tous du problème racine, la séparation d'avec Dieu$bp$, TRUE, 2),
      ('dacaa9b5-c40e-4759-8d8d-80cd63ca65c9', '48ab320a-0112-4d98-9c62-a877ecfc0158', $bp$Symptoms return because people stop trying, and need the support of a stronger system$bp$, $bp$Les symptômes reviennent parce que les gens cessent d'essayer, et ont besoin du soutien d'un système plus fort$bp$, FALSE, 3),
      ('be8d5701-d41e-4b27-b579-58791e4e0746', 'd3a057e3-f742-4c5c-aebb-86b119bcf3da', $bp$The thing you have been believing about life, God, and yourselves is wrong, so change your mind$bp$, $bp$Ce que vous avez cru au sujet de la vie, de Dieu et de vous-mêmes est faux, alors changez d'esprit$bp$, TRUE, 0),
      ('7b732709-c606-4dbf-8ddc-5bb557301c83', 'd3a057e3-f742-4c5c-aebb-86b119bcf3da', $bp$The thing you have inherited from your fathers is a curse, so break it by your own effort$bp$, $bp$Ce que vous avez hérité de vos pères est une malédiction, alors brisez-la par votre propre effort$bp$, FALSE, 1),
      ('9f47eb47-ce7f-4d60-9d4e-0c19860b5798', 'd3a057e3-f742-4c5c-aebb-86b119bcf3da', $bp$The thing you have been doing in secret is known to God, so feel guilty and confess it$bp$, $bp$Ce que vous faites en secret est connu de Dieu, alors sentez-vous coupables et confessez-le$bp$, FALSE, 2),
      ('5feb1c17-ea85-4b97-9995-68bcc56a8457', 'd3a057e3-f742-4c5c-aebb-86b119bcf3da', $bp$The thing you have been waiting for is coming soon, so prepare yourselves by fasting$bp$, $bp$Ce que vous attendez va bientôt venir, alors préparez-vous par le jeûne$bp$, FALSE, 3),
      ('9321c56c-b72d-4300-9c7e-7c16a5891c29', '57f01c51-a746-4cec-8df7-9c0d28f3280f', $bp$The son who said yes did the will of his father, since his words showed respect and honour for his father$bp$, $bp$Le fils qui a dit oui a fait la volonté de son père, puisque ses paroles montraient respect et honneur pour son père$bp$, FALSE, 0),
      ('318b35ad-8aad-4e0a-8728-70cb5ab86740', '57f01c51-a746-4cec-8df7-9c0d28f3280f', $bp$The son who changed his mind and went did his father's will; words alone are not repentance$bp$, $bp$Le fils qui a changé d'avis et y est allé a fait la volonté de son père ; les paroles seules ne sont pas la repentance$bp$, TRUE, 1),
      ('b4c20d44-7af3-4a1a-8a8c-21ff97e8dbe9', '57f01c51-a746-4cec-8df7-9c0d28f3280f', $bp$Both sons did the will of their father, since each one had good intentions in his heart$bp$, $bp$Les deux fils ont fait la volonté de leur père, puisque chacun avait de bonnes intentions dans le cœur$bp$, FALSE, 2),
      ('697fc0c3-fee1-4366-b407-9278b7cc708b', '57f01c51-a746-4cec-8df7-9c0d28f3280f', $bp$The son who refused was condemned, because a refusal can never be forgiven or reversed$bp$, $bp$Le fils qui a refusé a été condamné, parce qu'un refus ne peut jamais être pardonné ni annulé$bp$, FALSE, 3),
      ('670997f5-0d6a-4f5c-bfb3-040af153d573', '1e45b38c-7fa7-47cf-9284-e4be3686659c', $bp$His change was too late, since God had already closed the door of mercy before he spoke$bp$, $bp$Son changement est venu trop tard, puisque Dieu avait déjà fermé la porte de la miséricorde avant qu'il parle$bp$, FALSE, 0),
      ('7ba5a554-a36f-4c99-afa8-cef98947d2a9', '1e45b38c-7fa7-47cf-9284-e4be3686659c', $bp$His change was real, but God judged him anyway, since his sins were too great to forgive and could not be undone$bp$, $bp$Son changement était réel, mais Dieu l'a jugé quand même, puisque ses péchés étaient trop grands pour être pardonnés et ne pouvaient être effacés$bp$, FALSE, 1),
      ('37bee030-c1b0-4b45-aa1a-d72e23e8d9cf', '1e45b38c-7fa7-47cf-9284-e4be3686659c', $bp$His words were never spoken aloud, and God cannot accept a repentance that is not heard$bp$, $bp$Ses paroles n'ont jamais été dites à voix haute, et Dieu ne peut accepter une repentance qui n'est pas entendue$bp$, FALSE, 2),
      ('9ece8106-fdc7-48fa-8db7-803a11404e74', '1e45b38c-7fa7-47cf-9284-e4be3686659c', $bp$His words changed, but when the pressure lifted he went back, because real change would have cost him$bp$, $bp$Ses paroles ont changé, mais quand la pression a cessé il est retourné en arrière, parce qu'un vrai changement lui aurait coûté$bp$, TRUE, 3),
      ('cc6c26bd-8a86-4c50-a0c2-9191c5a7e826', '749382c9-66c9-4f59-ad07-33897d59554f', $bp$A wealthy man can buy forgiveness by giving back more than he took from others$bp$, $bp$Un homme riche peut acheter le pardon en rendant plus qu'il n'a pris aux autres$bp$, FALSE, 0),
      ('8ccf437f-1574-451f-ac13-25ae8fa95eea', '749382c9-66c9-4f59-ad07-33897d59554f', $bp$A public sinner must be accepted by the people before God will accept him$bp$, $bp$Un pécheur public doit être accepté par les gens avant que Dieu l'accepte$bp$, FALSE, 1),
      ('c8cb059c-fa58-4ce4-acda-983b787d120b', '749382c9-66c9-4f59-ad07-33897d59554f', $bp$A tax collector is judged by a different law from the one that judges others$bp$, $bp$Un collecteur d'impôts est jugé par une loi différente de celle qui juge les autres$bp$, FALSE, 2),
      ('15c5e678-5ee9-45df-9303-78c0437941f8', '749382c9-66c9-4f59-ad07-33897d59554f', $bp$A changed mind produces a changed action that you can actually see and count$bp$, $bp$Un esprit changé produit une action changée qu'on peut vraiment voir et compter$bp$, TRUE, 3),
      ('5b8349f0-9f61-4879-8a3a-082e2723f47b', '243817d3-f268-4427-a894-c88b93dd3b22', $bp$The old life is forgotten, not buried, because God removes it from every memory$bp$, $bp$L'ancienne vie est oubliée, non ensevelie, parce que Dieu l'efface de toute mémoire$bp$, FALSE, 0),
      ('36b08958-144f-42dc-997c-68caaa7fbbcf', '243817d3-f268-4427-a894-c88b93dd3b22', $bp$The old life is kept, not buried, because a believer returns to it from time to time$bp$, $bp$L'ancienne vie est gardée, non ensevelie, parce que le croyant y retourne de temps en temps$bp$, FALSE, 1),
      ('af325ec6-b1d0-40ef-a149-0bc6f01b2fac', '243817d3-f268-4427-a894-c88b93dd3b22', $bp$The old life is cleaned, not buried, because God improves what is already there$bp$, $bp$L'ancienne vie est nettoyée, non ensevelie, parce que Dieu améliore ce qui est déjà là$bp$, FALSE, 2),
      ('6f654ece-1d3e-416b-bbdc-6477a1e1869e', '243817d3-f268-4427-a894-c88b93dd3b22', $bp$The old life is buried, not paused, because you do not dig up what has been buried$bp$, $bp$L'ancienne vie est ensevelie, non mise en pause, parce qu'on ne déterre pas ce qui a été enseveli$bp$, TRUE, 3),
      ('345645fd-8b6b-4bbe-9a13-409c8dd232b0', '6ec2f5e6-b8a1-4172-b143-885f902dbfb4', $bp$Baptism first, then forty days of fasting, then the Spirit descended on Him in the desert$bp$, $bp$D'abord le baptême, puis quarante jours de jeûne, puis l'Esprit est descendu sur lui dans le désert$bp$, FALSE, 0),
      ('8e45836a-59bc-45fc-b435-0ee0c7697e8c', '6ec2f5e6-b8a1-4172-b143-885f902dbfb4', $bp$Baptism first, then the Spirit descended, then the Father spoke identity over Him$bp$, $bp$D'abord le baptême, puis l'Esprit est descendu, puis le Père a déclaré son identité sur lui$bp$, TRUE, 1),
      ('189a938b-f288-4710-ae78-4114a3d54c3b', '6ec2f5e6-b8a1-4172-b143-885f902dbfb4', $bp$The Spirit first, then baptism, then the Father spoke identity over Him after forty days$bp$, $bp$D'abord l'Esprit, puis le baptême, puis le Père a déclaré son identité sur lui après quarante jours$bp$, FALSE, 2),
      ('1de085ba-4889-4316-87ad-cde29b743ccb', '6ec2f5e6-b8a1-4172-b143-885f902dbfb4', $bp$The Father's voice first, then baptism, then the Spirit descended after He had prayed$bp$, $bp$D'abord la voix du Père, puis le baptême, puis l'Esprit est descendu après qu'il eut prié$bp$, FALSE, 3),
      ('d41c5902-ac67-4f33-89da-0a363d231610', 'd61d4973-7c9e-47e3-b4fd-ad2e87cdec8a', $bp$Anyone at all, since it is the church that decides when a person is ready to be baptized into the church$bp$, $bp$N'importe qui, puisque c'est l'Église qui décide quand une personne est prête à être baptisée dans l'Église$bp$, FALSE, 0),
      ('ccfd81fe-904d-4504-b2c5-42706902301d', 'd61d4973-7c9e-47e3-b4fd-ad2e87cdec8a', $bp$People who believe: it is a choice made by someone who has already decided to follow Christ$bp$, $bp$Les personnes qui croient : c'est un choix fait par quelqu'un qui a déjà décidé de suivre Christ$bp$, TRUE, 1),
      ('b40fa84c-9b27-429d-bf56-1a524c3206b0', 'd61d4973-7c9e-47e3-b4fd-ad2e87cdec8a', $bp$Only the members of a believer's family, who must all be baptized together on one day$bp$, $bp$Seulement les membres de la famille d'un croyant, qui doivent tous être baptisés ensemble un même jour$bp$, FALSE, 2),
      ('49361c57-3695-4741-9e5f-b608a9a869e1', 'd61d4973-7c9e-47e3-b4fd-ad2e87cdec8a', $bp$Only those who have first completed a long period of study and have a good reputation$bp$, $bp$Seulement ceux qui ont d'abord terminé une longue période d'étude et ont une bonne réputation$bp$, FALSE, 3),
      ('49454094-f50a-4d97-9180-cecc743b168c', 'f1ff5825-dc64-4db9-98be-81bfcb7915db', $bp$Both point to the same reality: one God revealed in three ways, so they call on the same name$bp$, $bp$Les deux désignent la même réalité : un seul Dieu révélé de trois manières, donc elles invoquent le même nom$bp$, TRUE, 0),
      ('23cc1b74-fb93-4e31-9923-f185a49a5474', 'f1ff5825-dc64-4db9-98be-81bfcb7915db', $bp$They point to two different eras, one before the cross and one after the resurrection$bp$, $bp$Elles désignent deux époques différentes, l'une avant la croix et l'autre après la résurrection$bp$, FALSE, 1),
      ('7af3126f-0bb1-4f09-bbef-ce16af63ff35', 'f1ff5825-dc64-4db9-98be-81bfcb7915db', $bp$They point to two different baptisms, one for new believers and one for mature leaders$bp$, $bp$Elles désignent deux baptêmes différents, l'un pour les nouveaux croyants et l'autre pour les dirigeants mûrs$bp$, FALSE, 2),
      ('37214def-7129-49d3-956c-8b9870139cfc', 'f1ff5825-dc64-4db9-98be-81bfcb7915db', $bp$They point to two different Gods, who work together to bring each person into the Kingdom$bp$, $bp$Elles désignent deux dieux différents, qui travaillent ensemble pour faire entrer chaque personne dans le Royaume$bp$, FALSE, 3),
      ('8077eef7-ca7b-4f65-894f-d296cc41e1da', '592f7529-845a-48e9-a512-deea904fff31', $bp$It is not invisible or merely theoretical: something changes in the person, and it shows$bp$, $bp$Elle n'est ni invisible ni simplement théorique : quelque chose change dans la personne, et cela se voit$bp$, TRUE, 0),
      ('bd87730f-fb77-4ff8-a624-25febca0949f', '592f7529-845a-48e9-a512-deea904fff31', $bp$It is always silent and hidden, so that the person is the only one who can know it, and no one else will notice$bp$, $bp$Elle est toujours silencieuse et cachée, de sorte que seule la personne peut le savoir, et personne d'autre ne le remarque$bp$, FALSE, 1),
      ('f075bdad-86f6-45b0-bb22-d52840c3c684', '592f7529-845a-48e9-a512-deea904fff31', $bp$It is always delayed for years, so that the believer must wait with great patience$bp$, $bp$Elle est toujours retardée pendant des années, de sorte que le croyant doit attendre avec une grande patience$bp$, FALSE, 2),
      ('8bd0b13b-2944-42c0-ae65-130a5f064bf3', '592f7529-845a-48e9-a512-deea904fff31', $bp$It is always the same on every occasion, with the same words and in the same place$bp$, $bp$Elle est toujours la même à chaque occasion, avec les mêmes paroles et au même endroit$bp$, FALSE, 3),
      ('11679215-8ba4-405a-996d-3ee2e20d9e65', '7c860d99-48a2-499c-a9f4-c99b7a24c396', $bp$At Samaria, while Philip was still preaching and healing the sick in the city$bp$, $bp$À Samarie, pendant que Philippe prêchait encore et guérissait les malades dans la ville$bp$, FALSE, 0),
      ('3c982161-2cea-4f8e-8100-4e030dbdea7c', '7c860d99-48a2-499c-a9f4-c99b7a24c396', $bp$At Ephesus, while Paul was still teaching in the school of Tyrannus each day$bp$, $bp$À Éphèse, pendant que Paul enseignait encore dans l'école de Tyrannus chaque jour$bp$, FALSE, 1),
      ('2daaab43-0d00-413b-9942-0f69dd2a7abc', '7c860d99-48a2-499c-a9f4-c99b7a24c396', $bp$At the house of Cornelius, while Peter was still speaking the gospel to the Gentiles$bp$, $bp$Dans la maison de Corneille, pendant que Pierre parlait encore de l'Évangile aux non-Juifs$bp$, TRUE, 2),
      ('a14d7076-c07f-4ee3-9d08-f6e775329010', '7c860d99-48a2-499c-a9f4-c99b7a24c396', $bp$At the River Jordan, while John was still baptizing the crowds who had come to him$bp$, $bp$Au Jourdain, pendant que Jean baptisait encore les foules venues à lui$bp$, FALSE, 3),
      ('1ef5321e-bcae-4098-8b77-29ea33188ba1', '163bd6ee-4ecf-4f21-a3e8-891906b4f22b', $bp$Visions, dreams, miracles, prophecy, signs in the sky, and rule over the nations$bp$, $bp$Visions, songes, miracles, prophétie, signes dans le ciel et domination sur les nations$bp$, FALSE, 0),
      ('e5112f67-9903-41a5-abd0-665f9f4d12fa', '163bd6ee-4ecf-4f21-a3e8-891906b4f22b', $bp$Wealth, fame, health, long life, protection from enemies, and success in business$bp$, $bp$Richesse, célébrité, santé, longue vie, protection contre les ennemis et réussite en affaires$bp$, FALSE, 1),
      ('63173c49-4b48-4bc2-aec7-2ac0270fcb6c', '163bd6ee-4ecf-4f21-a3e8-891906b4f22b', $bp$Rest, silence, comfort, peace, freedom from trials, and an end to all temptation$bp$, $bp$Repos, silence, réconfort, paix, libération des épreuves et fin de toute tentation$bp$, FALSE, 2),
      ('3174497a-458b-4a1e-8b07-1bb8d3fae7bb', '163bd6ee-4ecf-4f21-a3e8-891906b4f22b', $bp$Power, boldness, fruit, gifts, help in prayer, and a confirmed identity$bp$, $bp$Puissance, hardiesse, fruit, dons, aide dans la prière et identité confirmée$bp$, TRUE, 3),
      ('7e4a4e5e-1805-496f-9447-6b7042710b47', 'b0aeec06-87c8-4d14-9645-13c41986d3db', $bp$He is a feeling to be worked up, so you must pray and fast until the feeling arrives$bp$, $bp$Il est un sentiment à provoquer, donc il faut prier et jeûner jusqu'à ce que le sentiment arrive$bp$, FALSE, 0),
      ('f07cda2c-4bef-4eea-84dd-d24e95263b69', 'b0aeec06-87c8-4d14-9645-13c41986d3db', $bp$He is a gift to be received, not earned, so you need not wait until you feel holy enough$bp$, $bp$Il est un don à recevoir, non à mériter, donc il n'est pas nécessaire d'attendre de se sentir assez saint$bp$, TRUE, 1),
      ('55fcb6d2-14e5-43ce-bfbd-88b1ffc552d3', 'b0aeec06-87c8-4d14-9645-13c41986d3db', $bp$He is a blessing for leaders, so ordinary believers must wait until they are chosen$bp$, $bp$Il est une bénédiction pour les dirigeants, donc les croyants ordinaires doivent attendre d'être choisis$bp$, FALSE, 2),
      ('7b4d8ea4-d5e3-4075-8a16-6813c3d6ffe0', 'b0aeec06-87c8-4d14-9645-13c41986d3db', $bp$He is a reward to be earned, so you must wait until you have proved that you are holy and set apart by God$bp$, $bp$Il est une récompense à mériter, donc il faut attendre d'avoir prouvé qu'on est saint et mis à part par Dieu$bp$, FALSE, 3),
      ('d36609f3-2a28-4ce3-a251-9bfd4e7f400a', '951e37a5-f4ef-41cb-9031-f8ee73709689', $bp$A child of God and an heir with Christ, not merely a sinner who has been forgiven$bp$, $bp$Un enfant de Dieu et un héritier avec Christ, et pas seulement un pécheur pardonné$bp$, TRUE, 0),
      ('5c249f50-d84e-45ad-ab5e-29b7f9e5f714', '951e37a5-f4ef-41cb-9031-f8ee73709689', $bp$A forgiven sinner and a member of a church, still waiting to be made worthy later$bp$, $bp$Un pécheur pardonné et un membre d'une Église, qui attend encore d'être rendu digne plus tard$bp$, FALSE, 1),
      ('2f119138-f92e-4720-9381-81a0bb0fb2f9', '951e37a5-f4ef-41cb-9031-f8ee73709689', $bp$A servant of God and a guest in His house, never quite equal to the sons of God$bp$, $bp$Un serviteur de Dieu et un invité dans sa maison, jamais tout à fait l'égal des fils de Dieu$bp$, FALSE, 2),
      ('4dc1690a-4c98-499b-97d8-63a271dd59e4', '951e37a5-f4ef-41cb-9031-f8ee73709689', $bp$A student of the Word and a learner in the church, who must earn each privilege$bp$, $bp$Un élève de la Parole et un apprenant dans l'Église, qui doit mériter chaque privilège$bp$, FALSE, 3),
      ('2b3e3f9a-a106-4c0d-9dae-02d84e02bf26', '0c3205ab-bc04-42e6-bdec-b13a49974c62', $bp$Waits at home until the king calls, and has no part in the affairs of other lands$bp$, $bp$Attend chez lui que le roi l'appelle, et n'a aucune part aux affaires des autres pays$bp$, FALSE, 0),
      ('6f1d4601-28ec-41e7-a9c3-272d9f6c6dcd', '0c3205ab-bc04-42e6-bdec-b13a49974c62', $bp$Carries the message, culture, and authority of the kingdom that sent him$bp$, $bp$Porte le message, la culture et l'autorité du royaume qui l'a envoyé$bp$, TRUE, 1),
      ('6faeb717-06dc-4256-a023-8ad55989fec8', '0c3205ab-bc04-42e6-bdec-b13a49974c62', $bp$Defends the borders of the kingdom, and fights those who come into its territory$bp$, $bp$Défend les frontières du royaume et combat ceux qui entrent sur son territoire$bp$, FALSE, 2),
      ('34c8ccc6-24ca-46ff-9bb6-89126da97a22', '0c3205ab-bc04-42e6-bdec-b13a49974c62', $bp$Speaks for himself, and builds his own reputation in the land where he is sent$bp$, $bp$Parle pour lui-même et se construit sa propre réputation dans le pays où il est envoyé$bp$, FALSE, 3),
      ('36a6d025-9f76-4941-b596-a3380adce281', 'e1344c9a-077b-4d96-b0f1-1eeb09e55ebc', $bp$TRUE$bp$, $bp$VRAI$bp$, TRUE, 0),
      ('543438ac-6c79-47fd-ae76-55f12d0db418', 'e1344c9a-077b-4d96-b0f1-1eeb09e55ebc', $bp$FALSE$bp$, $bp$FAUX$bp$, FALSE, 1),
      ('53c3aca8-bc0f-43b2-b6cf-4190d59a36e8', '9cb25a94-ad88-4410-8d60-61dfbd050263', $bp$TRUE$bp$, $bp$VRAI$bp$, FALSE, 0),
      ('0db2c352-0caa-488f-82fe-4f19a573549b', '9cb25a94-ad88-4410-8d60-61dfbd050263', $bp$FALSE$bp$, $bp$FAUX$bp$, TRUE, 1),
      ('0a82e1b9-a716-42fb-a6ec-633c4d9ba61f', 'ee4074ad-e6e6-4c8d-8f31-4a4ce1593c48', $bp$TRUE$bp$, $bp$VRAI$bp$, TRUE, 0),
      ('46fd2aec-5c8f-492f-b5a1-e5769b8275e2', 'ee4074ad-e6e6-4c8d-8f31-4a4ce1593c48', $bp$FALSE$bp$, $bp$FAUX$bp$, FALSE, 1),
      ('917f66fc-7135-469e-9b0b-b91ca6327ea3', '473bb196-93d2-4de1-8262-2a4c37772971', $bp$TRUE$bp$, $bp$VRAI$bp$, FALSE, 0),
      ('2344fd4c-3996-485d-83cc-bf4aa53cbb29', '473bb196-93d2-4de1-8262-2a4c37772971', $bp$FALSE$bp$, $bp$FAUX$bp$, TRUE, 1),
      ('9f17c554-9357-4571-9c6c-03f21e20b6e1', '957a9288-15c9-4a92-af4c-d642f74e6720', $bp$TRUE$bp$, $bp$VRAI$bp$, TRUE, 0),
      ('7edb0800-a219-4e3b-9071-4c926d4855b6', '957a9288-15c9-4a92-af4c-d642f74e6720', $bp$FALSE$bp$, $bp$FAUX$bp$, FALSE, 1);
    INSERT INTO "PersonalQuestion" ("id", "assessmentId", "setNumber", "order", "kind", "textEn", "textFr", "bodyEn", "bodyFr", "guideEn", "guideFr", "required", "flagUnlessNone", "affectsStatus") VALUES
      ('b308a167-2886-46ef-bf74-e24d325401ce', a_id, 2, 0, 'CHOICE', $bp$Chapter Two says repentance is a change of mind that leads to a change of direction. Have you turned from your old way of living and given your life to Jesus Christ?$bp$, $bp$Le chapitre deux dit que la repentance est un changement d'esprit qui mène à un changement de direction. Vous êtes-vous détourné de votre ancienne manière de vivre et avez-vous donné votre vie à Jésus-Christ ?$bp$, NULL, NULL, $bp$Yes: ask what changed. Not yet, on the way, or not sure: explain that repentance is a decision, not a feeling (Chapter Two). Invite them to pray the Prayer of Repentance from Chapter Two with you.$bp$, $bp$Oui : demandez ce qui a changé. Pas encore, en chemin ou pas sûr : expliquez que la repentance est une décision, pas un sentiment (chapitre deux). Invitez la personne à prier avec vous la prière de repentance du chapitre deux.$bp$, TRUE, FALSE, TRUE),
      ('6b756264-dae3-45f3-b275-c3bc42822f44', a_id, 2, 1, 'CHOICE', $bp$Have you been baptized in water by immersion, going fully under the water and coming back up, after you believed in Jesus?$bp$, $bp$Avez-vous été baptisé d'eau par immersion, en descendant entièrement sous l'eau puis en ressortant, après avoir cru en Jésus ?$bp$, NULL, NULL, $bp$Yes, fully immersed after believing: this is the book's pattern (baptidzo means to immerse; Romans 6:3-4). Sprinkled or baptized before believing: gently explain that the book teaches believer's baptism by immersion, and arrange it. Not yet: do not wait; arrange it as soon as possible, as every example in Acts did.$bp$, $bp$Oui, immergé après avoir cru : c'est le modèle du livre (baptidzo signifie immerger ; Romains 6.3-4). Aspergé ou baptisé avant de croire : expliquez avec douceur que le livre enseigne le baptême du croyant par immersion, et organisez-le. Pas encore : n'attendez pas ; organisez-le dès que possible, comme tous les exemples des Actes.$bp$, TRUE, FALSE, FALSE),
      ('ee5d3234-ec79-48a8-b16f-f82407124ef9', a_id, 2, 2, 'TEXT', $bp$If yes, when and where were you baptized, and who baptized you?$bp$, $bp$Si oui, quand et où avez-vous été baptisé, et qui vous a baptisé ?$bp$, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE),
      ('067fcacb-f3b7-44e5-a737-0171b6e603bd', a_id, 2, 3, 'CHOICE', $bp$Have you received the Holy Spirit, with the evidence of speaking in other tongues, as in Acts 2, 10 and 19?$bp$, $bp$Avez-vous reçu le Saint-Esprit, avec pour preuve de parler en d'autres langues, comme en Actes 2, 10 et 19 ?$bp$, NULL, NULL, $bp$Yes with tongues: celebrate. Have the Spirit but no tongues, not yet, or need explaining: teach Luke 11:13 (a gift received by asking), and the examples at Pentecost, Cornelius, and Ephesus where they spoke in tongues. Offer to pray with laying on of hands (Acts 8:17; 19:6).$bp$, $bp$Oui avec les langues : réjouissez-vous. A l'Esprit mais pas de langues, pas encore, ou besoin d'explication : enseignez Luc 11.13 (un don reçu en demandant) et les exemples de la Pentecôte, de Corneille et d'Éphèse où ils ont parlé en langues. Proposez de prier avec imposition des mains (Actes 8.17 ; 19.6).$bp$, TRUE, FALSE, FALSE),
      ('7c152d07-560b-4bd0-a239-45dc0d86273a', a_id, 2, 4, 'TEXT', $bp$If yes, when and how did you receive Him?$bp$, $bp$Si oui, quand et comment l'avez-vous reçu ?$bp$, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE),
      ('22f94145-1dc7-467f-904e-c22a7f44890a', a_id, 2, 5, 'TEXT', $bp$Chapter Three says the old life is buried and a new life begins. What has changed in your life since you made your decision for Christ?$bp$, $bp$Le chapitre trois dit que l'ancienne vie est ensevelie et qu'une nouvelle vie commence. Qu'est-ce qui a changé dans votre vie depuis que vous avez pris votre décision pour Christ ?$bp$, NULL, NULL, $bp$Look for real change: new desire for the Word, freedom, changed habits. If "nothing yet", treat it as an open door for a conversation.$bp$, $bp$Cherchez un vrai changement : nouveau désir de la Parole, liberté, habitudes changées. Si « rien encore », voyez-y une porte ouverte pour une conversation.$bp$, TRUE, FALSE, FALSE),
      ('ed95b09e-d7ab-45af-8a4e-9c57f7945dc4', a_id, 2, 6, 'TEXT', $bp$What is the one thing, if any, that is holding you back from taking the next step in the doorway (repentance, baptism, or the Holy Spirit)? If nothing, write "nothing".$bp$, $bp$Quelle est la seule chose, s'il y en a une, qui vous retient de franchir la prochaine étape de la porte d'entrée (repentance, baptême ou Saint-Esprit) ? S'il n'y a rien, écrivez « rien ».$bp$, NULL, NULL, $bp$Read this with care and pray over it. Name the barrier gently, and answer it from the book. Note them for follow-up.$bp$, $bp$Lisez avec soin et priez à ce sujet. Nommez doucement l'obstacle et répondez-y à partir du livre. Notez la personne pour un suivi.$bp$, TRUE, TRUE, FALSE),
      ('aac8b8f6-c973-44d0-826a-94c34603f0f2', a_id, 2, 7, 'CHOICE', $bp$My Confession of Faith$bp$, $bp$Ma confession de foi$bp$, $bp$Read this confession slowly, and think about every word. If it is the true desire of your heart, tick "I agree". If you are not ready, tick "I do not agree". You will not be judged for being honest.
    INSERT INTO "PersonalOption" ("id", "questionId", "order", "textEn", "textFr", "signal") VALUES
      ('211398c1-4e6f-411c-8ea3-21c0b3452239', 'b308a167-2886-46ef-bf74-e24d325401ce', 0, $bp$Yes, I have turned, and I have received Jesus as my Lord and Saviour$bp$, $bp$Oui, je me suis détourné, et j'ai reçu Jésus comme mon Seigneur et Sauveur$bp$, 'POSITIVE'),
      ('40489bca-a7b0-4d0a-88e3-54ffd4d7a907', 'b308a167-2886-46ef-bf74-e24d325401ce', 1, $bp$I am on the way, but I have not fully turned yet$bp$, $bp$Je suis en chemin, mais je ne me suis pas encore pleinement détourné$bp$, 'NEEDS_TALK'),
      ('5b4705d4-6ba4-4bbc-a42e-c313679c8eef', 'b308a167-2886-46ef-bf74-e24d325401ce', 2, $bp$Not yet$bp$, $bp$Pas encore$bp$, 'NEEDS_TALK'),
      ('5ff8e96b-2181-4b14-bb2d-9555348d6aef', 'b308a167-2886-46ef-bf74-e24d325401ce', 3, $bp$I am not sure what this means for me$bp$, $bp$Je ne suis pas sûr de ce que cela signifie pour moi$bp$, 'NEEDS_TALK'),
      ('d65035dd-9d54-4c76-91d1-62ce3b16db33', '6b756264-dae3-45f3-b275-c3bc42822f44', 0, $bp$Yes, I was fully immersed in water after I believed$bp$, $bp$Oui, j'ai été entièrement immergé dans l'eau après avoir cru$bp$, 'POSITIVE'),
      ('f3fb28ed-4d27-4e9a-a334-9201c200fc43', '6b756264-dae3-45f3-b275-c3bc42822f44', 1, $bp$Yes, but I was sprinkled, or I was baptized before I believed$bp$, $bp$Oui, mais j'ai été aspergé, ou j'ai été baptisé avant de croire$bp$, 'NEEDS_TALK'),
      ('25d8e37c-fedf-4be6-b88b-432850a8cfa7', '6b756264-dae3-45f3-b275-c3bc42822f44', 2, $bp$No, I have not been baptized yet, but I want to be baptized now$bp$, $bp$Non, je n'ai pas encore été baptisé, mais je veux être baptisé maintenant$bp$, 'NEEDS_TALK'),
      ('43c6c44d-98f1-4f4a-9af5-b1e7d5ac3ccc', '6b756264-dae3-45f3-b275-c3bc42822f44', 3, $bp$No, I am not sure that baptism is needed$bp$, $bp$Non, je ne suis pas sûr que le baptême soit nécessaire$bp$, 'NEEDS_TALK'),
      ('df8f43d3-6dd1-4dc1-b51c-fde73569846e', '067fcacb-f3b7-44e5-a737-0171b6e603bd', 0, $bp$Yes, I have received the Holy Spirit, and I speak in other tongues$bp$, $bp$Oui, j'ai reçu le Saint-Esprit, et je parle en d'autres langues$bp$, 'POSITIVE'),
      ('321b83f9-6754-4783-ac1a-0a990dbeca55', '067fcacb-f3b7-44e5-a737-0171b6e603bd', 1, $bp$I believe I have the Holy Spirit, but I have not yet spoken in other tongues$bp$, $bp$Je crois avoir le Saint-Esprit, mais je n'ai pas encore parlé en d'autres langues$bp$, 'NEEDS_TALK'),
      ('78f83694-c6ec-4c38-a895-2fc4479dd9c4', '067fcacb-f3b7-44e5-a737-0171b6e603bd', 2, $bp$Not yet, but I want to receive Him now$bp$, $bp$Pas encore, mais je veux le recevoir maintenant$bp$, 'NEEDS_TALK'),
      ('261d72ae-93ec-4495-b2ca-2c08fe95d3a1', '067fcacb-f3b7-44e5-a737-0171b6e603bd', 3, $bp$I need someone to explain this to me$bp$, $bp$J'ai besoin que quelqu'un m'explique cela$bp$, 'NEEDS_TALK'),
      ('324d85f8-8937-4043-b9b7-fdaee53393a4', 'aac8b8f6-c973-44d0-826a-94c34603f0f2', 0, $bp$I agree with this confession, and I make it my own$bp$, $bp$Je suis d'accord avec cette confession, et je la fais mienne$bp$, 'POSITIVE'),
      ('993807a2-c88f-4e3c-bfeb-f9b2fd32eca6', 'aac8b8f6-c973-44d0-826a-94c34603f0f2', 1, $bp$I do not agree with this confession$bp$, $bp$Je ne suis pas d'accord avec cette confession$bp$, 'NEEDS_TALK');
