-- Book 2's exam (2 question sets, English and French), written by the founder
-- (the French was translated for him to review). A set loads only when the book's
-- exam exists and has nothing in that set yet, so nothing he already wrote is
-- replaced. It only loads while the exam is still a draft (members cannot reach
-- it), and the exam stays a draft: he publishes it himself once he has read it.
DO $load$
DECLARE
  a_id TEXT;
BEGIN
  SELECT e."id" INTO a_id
  FROM "Assessment" e
  JOIN "LibraryBook" b ON b."id" = e."trainingBookId"
  WHERE b."kind" = 'TRAINING' AND b."trainingOrder" = 2 AND e."status" = 'DRAFT';
  IF a_id IS NULL THEN
    RETURN;
  END IF;

  -- Set 1: 25 marked questions and 8 personal ones.
  IF NOT EXISTS (SELECT 1 FROM "Question" WHERE "assessmentId" = a_id AND "setNumber" = 1)
     AND NOT EXISTS (SELECT 1 FROM "PersonalQuestion" WHERE "assessmentId" = a_id AND "setNumber" = 1) THEN

I confess with my mouth that Jesus Christ is my Lord and Saviour, and I believe in my heart that God raised Him from the dead. I turn from my old way of living and I give my life to Him. I believe that my old life is buried with Christ, and that I now walk in newness of life. I commit to follow Him in water baptism, and I receive by faith the Holy Spirit He has promised. I belong to the Kingdom of God.$bp$, $bp$Lisez cette confession lentement et réfléchissez à chaque mot. Si c'est le vrai désir de votre cœur, cochez « Je suis d'accord ». Si vous n'êtes pas prêt, cochez « Je ne suis pas d'accord ». Vous ne serez pas jugé pour votre honnêteté.

Je confesse de ma bouche que Jésus-Christ est mon Seigneur et Sauveur, et je crois dans mon cœur que Dieu l'a ressuscité des morts. Je me détourne de mon ancienne manière de vivre et je lui donne ma vie. Je crois que mon ancienne vie est ensevelie avec Christ, et que je marche maintenant dans une vie nouvelle. Je m'engage à le suivre dans le baptême d'eau, et je reçois par la foi le Saint-Esprit qu'il a promis. J'appartiens au Royaume de Dieu.$bp$, $bp$Agree: celebrate with them, and ask them in their own words what they have decided. Then follow up on the two steps they still need: baptism by immersion and receiving the Holy Spirit with tongues, if not yet done. Do not agree: do not pressure or judge them. Ask which part they cannot say yet, answer gently from the book, and pray.$bp$, $bp$D'accord : réjouissez-vous avec elle et demandez-lui avec ses propres mots ce qu'elle a décidé. Puis suivez les deux étapes qui lui restent : le baptême par immersion et la réception du Saint-Esprit avec les langues, si ce n'est pas encore fait. Pas d'accord : ne la pressez pas et ne la jugez pas. Demandez quelle partie elle ne peut pas encore dire, répondez doucement à partir du livre, et priez.$bp$, TRUE, FALSE, TRUE);
  END IF;

  -- Set 2: 25 marked questions and 8 personal ones.
  IF NOT EXISTS (SELECT 1 FROM "Question" WHERE "assessmentId" = a_id AND "setNumber" = 2)
     AND NOT EXISTS (SELECT 1 FROM "PersonalQuestion" WHERE "assessmentId" = a_id AND "setNumber" = 2) THEN

I confess with my mouth that Jesus Christ is my Lord and Saviour, and I believe in my heart that God raised Him from the dead. I turn from my old way of living and I give my life to Him. I believe that my old life is buried with Christ, and that I now walk in newness of life. I commit to follow Him in water baptism, and I receive by faith the Holy Spirit He has promised. I belong to the Kingdom of God.$bp$, $bp$Lisez cette confession lentement et réfléchissez à chaque mot. Si c'est le vrai désir de votre cœur, cochez « Je suis d'accord ». Si vous n'êtes pas prêt, cochez « Je ne suis pas d'accord ». Vous ne serez pas jugé pour votre honnêteté.

Je confesse de ma bouche que Jésus-Christ est mon Seigneur et Sauveur, et je crois dans mon cœur que Dieu l'a ressuscité des morts. Je me détourne de mon ancienne manière de vivre et je lui donne ma vie. Je crois que mon ancienne vie est ensevelie avec Christ, et que je marche maintenant dans une vie nouvelle. Je m'engage à le suivre dans le baptême d'eau, et je reçois par la foi le Saint-Esprit qu'il a promis. J'appartiens au Royaume de Dieu.$bp$, $bp$Agree: celebrate with them, and ask them in their own words what they have decided. Then follow up on the two steps they still need: baptism by immersion and receiving the Holy Spirit with tongues, if not yet done. Do not agree: do not pressure or judge them. Ask which part they cannot say yet, answer gently from the book, and pray.$bp$, $bp$D'accord : réjouissez-vous avec elle et demandez-lui avec ses propres mots ce qu'elle a décidé. Puis suivez les deux étapes qui lui restent : le baptême par immersion et la réception du Saint-Esprit avec les langues, si ce n'est pas encore fait. Pas d'accord : ne la pressez pas et ne la jugez pas. Demandez quelle partie elle ne peut pas encore dire, répondez doucement à partir du livre, et priez.$bp$, TRUE, FALSE, TRUE);
  END IF;
END
$load$;
